"""Fused MoE (MXFP4 weights, MX-fp8 activations, gate/up-interleaved clamped SiLU, expert mask, num_local_tokens):
a FlyDSL prologue routes the received rows, quantizes x to MX-fp8 and zeroes ``out``; stage 1 (gate/up GEMM, clamped
SiLU, MX-fp8 output) and stage 2 (down GEMM, atomic adds into ``out``) follow, configured per token count."""

import functools
import math as _math
import re
from collections.abc import Callable
from contextlib import contextmanager
from dataclasses import dataclass

import flydsl.compiler as flyc
import flydsl.expr as fx
import torch
from flydsl._mlir import ir
from flydsl._mlir.dialects import arith as std_arith
from flydsl._mlir.dialects import llvm, memref, scf
from flydsl._mlir.dialects import vector as _vector
from flydsl._mlir.dialects.arith import CmpIPredicate
from flydsl.compiler.kernel_function import CompilationContext
from flydsl.expr import arith, const_expr, gpu, range_constexpr, rocdl
from flydsl.expr.arith import ArithValue
from flydsl.expr.meta import dsl_loc_tracing
from flydsl.expr.typing import T, as_ir_value
from flydsl.runtime.device import get_rocm_arch
from flydsl.utils.smem_allocator import SmemAllocator, SmemPtr

# ---- from layout_utils ------------------------------------------------------------


def _is_pow2(n):
    return n > 0 and (n & (n - 1)) == 0


def _div_pow2(val, divisor):
    """Unsigned divide by a compile-time power of two, as a shift instead of a divui."""
    shift = _math.log2(divisor)
    assert shift == int(shift), f"{divisor} is not a power of 2"
    return arith.shrui(val, arith.index(int(shift)))


def _mod_pow2(val, modulus):
    """Unsigned remainder by a compile-time power of two, as a mask instead of a remui."""
    return arith.andi(val, arith.index(modulus - 1))


def _parse_dim(tok):
    tok = tok.strip()
    return None if tok == "?" else int(tok)


def _parse_layout(ly):
    """Parse '(s0,s1,...):(d0,d1,...)' into (shapes, strides), None for a dynamic entry."""
    ly_str = str(ly.type) if hasattr(ly, "type") else str(ly)
    m = re.search(r"\(([^)]+)\):\(([^)]+)\)", ly_str)
    if not m:
        return None
    shapes = [_parse_dim(s) for s in m.group(1).split(",")]
    strides = [_parse_dim(s) for s in m.group(2).split(",")]
    return shapes, strides


def _has_dynamic_strides(strides):
    return any(s is None for s in strides)


def idx2crd(idx, layout):
    """Flat index to coordinates of a static layout, with shift/mask for power-of-two strides and sizes."""
    if hasattr(idx, "ir_value"):
        idx = idx.ir_value()
    if isinstance(idx, ir.Value) and not isinstance(idx.type, ir.IndexType):
        idx = arith.index_cast(T.index, idx)
    shapes, strides = _parse_layout(layout)
    ndims = len(strides)

    ordered = sorted(
        [(i, s, sz) for i, s, sz in zip(range(ndims), strides, shapes) if s != 0],
        key=lambda x: x[1],
        reverse=True,
    )
    coords = [None] * ndims
    remaining = idx
    for i, stride_val, size_val in ordered:
        if stride_val == 1:
            c = remaining
        elif _is_pow2(stride_val):
            c = _div_pow2(remaining, stride_val)
        else:
            c = remaining / arith.index(stride_val)
        if size_val is not None:
            if _is_pow2(size_val):
                c = _mod_pow2(c, size_val)
            else:
                c = c % arith.index(size_val)
        coords[i] = c
    for i in range(ndims):
        if coords[i] is None:
            coords[i] = remaining
    return coords


def crd2idx(crd, layout):
    """Coordinates to flat index: plain arith ops on a static layout, fx.crd2idx on a dynamic one."""
    parsed = _parse_layout(layout)

    if parsed is None or _has_dynamic_strides(parsed[1]):
        # fly.make_coord requires i32/i64, not index
        crd_i32 = []
        for c in crd:
            cv = c
            if isinstance(cv, ArithValue):
                cv = cv.ir_value() if hasattr(cv, "ir_value") else cv
            if isinstance(cv, ir.Value) and isinstance(cv.type, ir.IndexType):
                cv = arith.index_cast(T.i32, cv)
            crd_i32.append(cv)
        coord_val = fx.make_coord(*crd_i32)
        scalar = fx.get_scalar(fx.crd2idx(coord_val, layout)).ir_value()
        if not isinstance(scalar.type, ir.IndexType):
            scalar = arith.index_cast(T.index, scalar)
        return scalar if isinstance(scalar, ArithValue) else ArithValue(scalar)

    _, strides = parsed
    result = None
    for coord_v, stride_v in zip(crd, strides):
        if stride_v == 0:
            continue
        term = coord_v if stride_v == 1 else coord_v * arith.index(stride_v)
        result = term if result is None else result + term
    return result if result is not None else arith.index(0)


def get(int_tuple, mode):
    return int_tuple[mode]


# ---- from buffer_ops ------------------------------------------------------------

# V# flags word on CDNA: the nonzero data and number formats the raw buffer intrinsics require.
_BUFFER_FLAGS = 7 << 12 | 4 << 15


def _bo_unwrap_value(value):
    """Unwrap DSL wrappers (``ir_value()``, ``_value``, ``value``) down to the MLIR value."""
    if hasattr(value, "ir_value") and (not isinstance(value, ir.Value)):
        return value.ir_value()
    max_depth = 10
    depth = 0
    while depth < max_depth and (not isinstance(value, ir.Value)):
        if hasattr(value, "_value"):
            value = value._value
        elif hasattr(value, "value"):
            value = value.value
        else:
            break
        depth += 1
    return value


@dsl_loc_tracing
def _bo_create_i32_constant(value: int) -> ir.Value:
    i32_type = T.i32
    if value > 2147483647:
        value = int(value - 2**32)
    attr = ir.IntegerAttr.get(i32_type, value)
    op = std_arith.ConstantOp(i32_type, attr)
    return _bo_unwrap_value(op.result)


def _bo_to_i32_offset(offset: ir.Value) -> ir.Value:
    """Normalize an index or integer offset to i32 (index_cast, trunc or sign-extend)."""
    ot = offset.type
    if isinstance(ot, ir.IntegerType):
        if ot.width == 32:
            return offset
        if ot.width > 32:
            return _bo_unwrap_value(std_arith.TruncIOp(T.i32, offset).result)
        return _bo_unwrap_value(std_arith.ExtSIOp(T.i32, offset).result)
    return _bo_unwrap_value(std_arith.IndexCastOp(T.i32, offset).result)


@dsl_loc_tracing
def _bo_create_i16_constant(value: int) -> ir.Value:
    i16_type = T.i16
    attr = ir.IntegerAttr.get(i16_type, value)
    op = std_arith.ConstantOp(i16_type, attr)
    return _bo_unwrap_value(op.result)


@dsl_loc_tracing
def _bo_create_i64_constant(value: int) -> ir.Value:
    i64_type = T.i64
    attr = ir.IntegerAttr.get(i64_type, value)
    op = std_arith.ConstantOp(i64_type, attr)
    return _bo_unwrap_value(op.result)


@dsl_loc_tracing
def _bo_create_buffer_resource_from_addr(
    addr_i64: ir.Value, *, num_records_bytes: int | ir.Value
) -> ir.Value:
    """Buffer resource (!llvm.ptr<8>) based at a raw i64 address, bounded to ``num_records_bytes``."""
    addr_i64 = _bo_unwrap_value(addr_i64)
    ptr_type = ir.Type.parse("!llvm.ptr")
    base_ptr = llvm.IntToPtrOp(ptr_type, addr_i64).result
    flags = _bo_create_i32_constant(_BUFFER_FLAGS)
    stride = _bo_create_i16_constant(0)
    if isinstance(num_records_bytes, int):
        nbytes = max(0, min(int(num_records_bytes), 4294967295))
        num_records = _bo_create_i64_constant(nbytes)
    else:
        num_records = _bo_unwrap_value(num_records_bytes)
        i64_type = T.i64
        if not isinstance(num_records.type, ir.IntegerType) or num_records.type.width != 64:
            if isinstance(num_records.type, ir.IndexType):
                num_records = _bo_unwrap_value(std_arith.IndexCastOp(i64_type, num_records).result)
            else:
                num_records = _bo_unwrap_value(std_arith.ExtSIOp(i64_type, num_records).result)
    rsrc_type = ir.Type.parse("!llvm.ptr<8>")
    return rocdl.MakeBufferRsrcOp(rsrc_type, base_ptr, stride, num_records, flags).result


@dsl_loc_tracing
def _bo_buffer_load(
    rsrc: ir.Value, offset: ir.Value, vec_width: int, dtype, cache_modifier: int = 0
) -> ir.Value:
    """Buffer load of ``vec_width`` elements of ``dtype`` at an offset in elements."""
    if hasattr(offset, "ir_value"):
        offset = offset.ir_value()
    offset = _bo_to_i32_offset(_bo_unwrap_value(offset))
    bytes_const = _bo_create_i32_constant(dtype.width // 8)
    offset = _bo_unwrap_value(std_arith.MulIOp(offset, bytes_const).result)
    result_type = dtype if vec_width == 1 else ir.VectorType.get([vec_width], dtype)
    soffset = _bo_create_i32_constant(0)
    aux_attr = ir.IntegerAttr.get(ir.IntegerType.get_signless(32), cache_modifier) if cache_modifier else None
    return rocdl.RawPtrBufferLoadOp(result_type, rsrc, offset, soffset, aux=aux_attr).result


@dsl_loc_tracing
def _bo_buffer_store_bytes(data: ir.Value, rsrc: ir.Value, offset: ir.Value):
    """Buffer store of ``data`` at an offset in bytes."""
    if hasattr(data, "ir_value"):
        data = data.ir_value()
    if hasattr(offset, "ir_value"):
        offset = offset.ir_value()
    data = _bo_unwrap_value(data)
    rsrc = _bo_unwrap_value(rsrc)
    offset = _bo_to_i32_offset(_bo_unwrap_value(offset))
    soffset = _bo_create_i32_constant(0)
    rocdl.RawPtrBufferStoreOp(data, rsrc, offset, soffset, aux=None)


# ---- from vector ------------------------------------------------------------


def _vec_as_index_ir_value(value):
    if isinstance(value, int):
        return arith.constant(value, index=True)
    v = as_ir_value(value)
    if isinstance(v.type, ir.IntegerType):
        v = std_arith.IndexCastOp(ir.IndexType.get(), v).result
    return v


@dsl_loc_tracing
def _vec_from_elements(result_type, elems):
    return _vector.from_elements(result_type, [as_ir_value(v) for v in elems])


@dsl_loc_tracing
def _vec_store(value, memref, indices, **kwargs):
    return _vector.store(
        as_ir_value(value), as_ir_value(memref), [_vec_as_index_ir_value(i) for i in indices], **kwargs
    )


@dsl_loc_tracing
def _vec_extract(vector, position):
    return _vector.ExtractOp(as_ir_value(vector), static_position=[position], dynamic_position=[]).result


@dsl_loc_tracing
def _vec_load_op(result_type, memref, indices):
    return _vector.LoadOp(
        result_type, as_ir_value(memref), [_vec_as_index_ir_value(i) for i in indices]
    ).result


@dsl_loc_tracing
def _vec_bitcast(result_type, source):
    return _vector.BitCastOp(result_type, as_ir_value(source)).result


# ---- from quant_utils ------------------------------------------------------------


def _raw(value):
    """Unwrap a DSL Numeric to a raw ir.Value (rocdl/inline_asm need raw operands)."""
    return value.ir_value() if hasattr(value, "ir_value") else value


# ---- from mfma_epilogues ------------------------------------------------------------


@contextmanager
def _if_then(if_op):
    """Then-region of an scf.IfOp, closed with a yield if the body did not end in one."""
    with ir.InsertionPoint(if_op.then_block):
        try:
            yield if_op.then_block
        finally:
            blk = if_op.then_block
            if (not blk.operations) or not isinstance(blk.operations[-1], scf.YieldOp):
                scf.YieldOp([])


def default_epilog(*, m_repeat: int, lane_div_16, body_row: Callable):
    """Call ``body_row(mi, ii, row_in_tile)`` for each row this lane holds in the MFMA C fragments."""
    lane_div_16_mul4 = lane_div_16 * 4
    ii_idx_list = [fx.Index(ii) for ii in range(4)]
    for mi in range_constexpr(m_repeat):
        mi_base = arith.constant(mi * 16, index=True)
        for ii in range_constexpr(4):
            row_in_tile = mi_base + (lane_div_16_mul4 + ii_idx_list[ii])
            body_row(mi=mi, ii=ii, row_in_tile=row_in_tile)


def c_shuffle_epilog(
    *,
    tile_m: int,
    tile_n: int,
    e_vec: int,
    cshuffle_nlane: int = 32,
    block_size: int,
    m_repeat: int,
    num_acc_n: int,
    tx,
    lane_div_16,
    lane_mod_16,
    bx_m,
    by_n,
    n_tile_base,
    lds_out,
    frag_elem_type: ir.Type,
    write_row_to_lds: Callable,
    precompute_row: Callable,
    store_pair: Callable,
):
    """LDS CShuffle epilogue: ``write_row_to_lds`` puts each MFMA row in ``lds_out``, then every lane reads back
    ``e_vec`` adjacent columns and calls ``store_pair`` on them. ``precompute_row`` returns ``(row_ctx, row_pred)``
    per row, loaded before the store loop; a row whose ``row_pred`` is false stores nothing."""
    cshuffle_mlane = block_size // cshuffle_nlane
    assert block_size % cshuffle_nlane == 0 and tile_m % cshuffle_mlane == 0
    assert tile_n % (cshuffle_nlane * e_vec) == 0

    tile_n_idx = arith.constant(tile_n, index=True)
    col_base_local = n_tile_base + lane_mod_16

    def _write_row(mi: int, ii: int, row_in_tile):
        write_row_to_lds(
            mi=mi,
            ii=ii,
            row_base_lds=row_in_tile * tile_n_idx,
            col_base_local=col_base_local,
            num_acc_n=num_acc_n,
            lds_out=lds_out,
        )

    # The barrier before the writes waits out the main loop's LDS reads of the same space.
    gpu.barrier()
    default_epilog(m_repeat=m_repeat, lane_div_16=lane_div_16, body_row=_write_row)
    gpu.barrier()

    m_reps_shuffle = tile_m // cshuffle_mlane
    n_reps_shuffle = tile_n // (cshuffle_nlane * e_vec)
    c_nlane = fx.Index(cshuffle_nlane)
    m_lane = tx // c_nlane
    n_lane = tx % c_nlane
    c_evec = fx.Index(e_vec)
    vec_frag = T.vec(e_vec, frag_elem_type)

    # Every row's context first, so its loads are in flight together rather than one wait per row.
    precomputed_rows = []
    for mr in range_constexpr(m_reps_shuffle):
        row_local = arith.constant(mr * cshuffle_mlane, index=True) + m_lane
        row = bx_m + row_local
        row_ctx, row_pred = precompute_row(row_local=row_local, row=row)
        precomputed_rows.append((row_local, row, row_ctx, row_pred))

    for mr in range_constexpr(m_reps_shuffle):
        row_local, row, row_ctx, row_pred = precomputed_rows[mr]

        def _do_store_row(row=row, row_ctx=row_ctx, row_local=row_local):
            row_base_lds = row_local * tile_n_idx
            for nr in range_constexpr(n_reps_shuffle):
                col_pair0 = arith.constant(nr * (cshuffle_nlane * e_vec), index=True) + (n_lane * c_evec)
                frag = _vec_load_op(vec_frag, lds_out, [row_base_lds + col_pair0])
                store_pair(row=row, row_ctx=row_ctx, col_g0=by_n + col_pair0, frag=frag)

        if row_pred is not None:
            with _if_then(scf.IfOp(row_pred)):
                _do_store_row()
        else:
            _do_store_row()


# ---- from mfma_preshuffle_pipeline ------------------------------------------------------------


def _mfma_p_crd2idx(crd, layout):
    """crd2idx returning an index-typed ir.Value (unwraps fly.int_tuple)."""
    scalar = fx.get_scalar(fx.crd2idx(crd, layout)).ir_value()
    if isinstance(scalar.type, ir.IndexType):
        return scalar
    return arith.IndexCastOp(T.index, scalar).result


def swizzle_xor16(row, col, k_blocks16):
    """XOR-with-row swizzle of the K byte column at 16 B granularity: col ^ ((row % k_blocks16) * 16)."""
    rem = arith.andi(row, k_blocks16 - arith.index(1))
    return col ^ (rem * 16)


def _buffer_load_vec(rsrc, idx, *, elem_type, vec_elems, offset_in_bytes, cache_modifier=0):
    """Load ``vec_elems`` one-byte elements as a dword-vector buffer_load + bitcast."""
    assert vec_elems % 8 == 0
    idx_i32 = arith.shrui(idx, arith.index(2)) if offset_in_bytes else idx
    i32_val = _bo_buffer_load(
        rsrc, idx_i32, vec_width=vec_elems // 4, dtype=T.i32, cache_modifier=cache_modifier
    )
    return _vec_bitcast(T.vec(vec_elems, elem_type), i32_val)


@dataclass(frozen=True)
class PreshuffleScaleLayout:
    """Strides of the preshuffled scale layout ``(c_mn1, c_k1, 4, 16)``: the flat index is
    ``mni * stride_n0 + ku * stride_k0 + k_lane * stride_klane + n_lane``."""

    stride_n0: object
    stride_k0: object
    stride_klane: object


def make_preshuffle_scale_layout(*, c_k: ir.Value) -> PreshuffleScaleLayout:
    """Strides of aiter/CK's preshuffled e8m0 scale layout for FP4/FP8 microscaling."""
    c16 = fx.Index(16)
    c4 = fx.Index(4)
    c_k1 = ((c_k // fx.Index(32)) // c4) // fx.Index(2)
    stride_klane = c16
    stride_k0 = c4 * stride_klane
    return PreshuffleScaleLayout(stride_n0=c_k1 * stride_k0, stride_k0=stride_k0, stride_klane=stride_klane)


def make_preshuffle_b_layout(*, c_n: ir.Value, c_k: ir.Value, kpack_bytes: int):
    """B layout of aiter/CK's preshuffle for one-byte MFMA operands, N-major blocks."""
    c16 = fx.Index(16)
    stride_nlane = fx.Index(kpack_bytes)
    n0 = c_n // c16
    c_k0 = c_k // fx.Index(64)
    stride_klane = c16 * stride_nlane
    stride_k0 = fx.Index(4) * stride_klane
    stride_n0 = c_k0 * stride_k0
    stride_b = tuple(
        arith.index_cast(T.i32, s) for s in (stride_n0, stride_k0, stride_klane, stride_nlane)
    ) + (1,)
    shape_b = (arith.index_cast(T.i32, n0), arith.index_cast(T.i32, c_k0), 4, 16, kpack_bytes)
    return fx.make_layout(shape_b, stride_b)


def tile_chunk_coord_i32(
    *, tx_i32_base: ir.Value, i: int, total_threads: int, layout_tile_div4, chunk_i32: int
):
    """Map (thread, chunk_id) -> (row_local, col_local_i32) for X/A loads."""
    chunk_off_i32 = arith.constant(i * total_threads * chunk_i32, index=True)
    coord_local = fx.idx2crd(fx.Int32(tx_i32_base + chunk_off_i32), layout_tile_div4)
    return fx.get(coord_local, 0), fx.get(coord_local, 1)


def lds_store_16b_xor16(
    *, lds_memref, vec16_ty, layout_lds, row_local, col_local_i32, k_blocks16, lds_base, vec_part
):
    """Store one 16 B chunk into LDS with CK's XOR16 swizzle on the K dimension."""
    col_swz = swizzle_xor16(row_local, col_local_i32 * arith.index(4), k_blocks16)
    idx0 = _mfma_p_crd2idx((fx.Int32(row_local), fx.Int32(col_swz)), layout_lds) + lds_base
    _vec_store(_vec_bitcast(vec16_ty, vec_part), lds_memref, [idx0])


# ---- from moe_sorting_kernel ------------------------------------------------------------

DPP_ROW_SHR_1 = 0x111
DPP_ROW_SHR_2 = 0x112
DPP_ROW_SHR_4 = 0x114
DPP_ROW_SHR_8 = 0x118
DPP_ROW_MASK = 0xF
DPP_BANK_MASK = 0xF


def _dpp_intra_wave_prefix_sum(val, lane):
    """Inclusive prefix sum over a wave64: DPP row shifts within each row of lanes, then ds_bpermute steps across
    the rows."""
    val_raw = _raw(val)
    zero_raw = _raw(fx.Int32(0))

    for shift, dpp_op in ((1, DPP_ROW_SHR_1), (2, DPP_ROW_SHR_2), (4, DPP_ROW_SHR_4), (8, DPP_ROW_SHR_8)):
        remote = rocdl.update_dpp(T.i32, zero_raw, val_raw, dpp_op, DPP_ROW_MASK, DPP_BANK_MASK, True)
        val = (lane >= fx.Int32(shift)).select(val + fx.Int32(remote), val)
        val_raw = _raw(val)

    src_lane_16 = (lane & fx.Int32(0x30)) - fx.Int32(1)
    remote16 = rocdl.ds_bpermute(T.i32, src_lane_16 * fx.Int32(4), val)
    val = (lane >= fx.Int32(16)).select(val + fx.Int32(remote16), val)

    src_lane_32 = (lane & fx.Int32(0x30)) - fx.Int32(17)
    remote32 = rocdl.ds_bpermute(T.i32, src_lane_32 * fx.Int32(4), val)
    return (lane >= fx.Int32(32)).select(val + fx.Int32(remote32), val)


# ---- from mixed_moe_gemm_2stage_common ------------------------------------------------------------


def barrier():
    """s_barrier as inline asm, so LLVM's SIInsertWaitcnts adds no conservative vmcnt(0) lgkmcnt(0) before it."""
    llvm.InlineAsmOp(
        res=None,
        operands_=[],
        asm_string="s_barrier",
        constraints="",
        has_side_effects=True,
        is_align_stack=False,
    )


# ---- from kernel ------------------------------------------------------------

_FP8_E4M3_MAX = 448.0
_AMAX_FLOOR_BITS = 0x2EDBE6FF  # 1e-10f, the activation quantizer's floor on |x| max

_S1_BASE = dict(tile_n=64, tile_k=256, waves_per_eu=16, b_nt=2)
_S2_BASE = dict(tile_n=128, tile_k=256, b_nt=2, k_rot=(1, 0, 0))
# Per token count: stage-1 and stage-2 overrides and the sort block; other counts take the bases and 32-row blocks.
_CFG = {
    16: ({"waves_per_eu": 7}, {"tile_k": 128, "tile_n": 64, "nw": 2}, 16),
    32: ({"waves_per_eu": 10}, {"tile_k": 128, "tile_n": 64, "nw": 2, "k_rot": (0, 1, 0)}, 16),
    64: ({}, {"tile_n": 64, "k_rot": (1, 3, 1)}, 16),
    128: ({}, {"tile_n": 64, "k_rot": (1, 3, 1)}, 16),
    256: ({"tile_k": 1024}, {"tile_n": 64, "k_rot": (1, 3, 1)}, 16),
}


def _p(p, dtype):
    return fx.recast_iter(dtype, p)


def _lds_add(arr, idx, value):
    llvm.AtomicRMWOp(
        llvm.AtomicBinOp.add,
        (arr.ptr + idx).llvm_ptr,
        _raw(value),
        llvm.AtomicOrdering.monotonic,
        syncscope="workgroup",
    )


def _ld4(p, off):
    return fx.Vector(fx.ptr_load(_p(p, fx.Int32) + off, T.vec(4, T.i32)))


def _st4(p, off, v):
    fx.ptr_store(_raw(v), _p(p, fx.Int32) + off)


@flyc.kernel
def _prologue(
    X: fx.Pointer,
    IDS: fx.Pointer,
    RW: fx.Pointer,
    MASK: fx.Pointer,
    SID: fx.Pointer,
    SW: fx.Pointer,
    SEID: fx.Pointer,
    NV: fx.Pointer,
    A1: fx.Pointer,
    A1S: fx.Pointer,
    OUT: fx.Pointer,
    NLT: fx.Pointer,
    M: fx.Constexpr[int],
    TOP: fx.Constexpr[int],
    G: fx.Constexpr[int],
    E: fx.Constexpr[int],
    D: fx.Constexpr[int],
    BM: fx.Constexpr[int],
):
    # Workgroup t: token t. Thread i holds hidden columns 16 i .. 16 i + 15 and the mask of global expert i.
    NT = D // 16
    assert NT == G
    t = fx.Int32(fx.gpu.block_idx.x)
    tid = fx.Int32(fx.gpu.thread_idx.x)
    lane = tid % 64
    wave = tid // 64
    R = M * TOP
    NIT = (R + NT - 1) // NT
    lds = fx.SharedAllocator()
    loc = lds.allocate(fx.Array[fx.Int32, G]).peek()
    itl = lds.allocate(fx.Array[fx.Int32, NIT * NT]).peek()
    hall = lds.allocate(fx.Array[fx.Int32, 64]).peek()
    hbef = lds.allocate(fx.Array[fx.Int32, 64]).peek()
    boff = lds.allocate(fx.Array[fx.Int32, 68]).peek()
    wc = lds.allocate(fx.Array[fx.Int32, 4]).peek()
    pos = lds.allocate(fx.Array[fx.Int32, 8]).peek()

    # Independent global traffic first: the hidden row, the mask, the routing ids, out's zero row.
    xb = t * (D // 2) + tid * 8
    x0 = _ld4(X, xb)
    x1 = _ld4(X, xb + 4)
    held = _p(MASK, fx.Int32)[tid] != 0
    # Routes of the rows this rank received (num_local_tokens); later rows route nowhere.
    nr = _p(NLT, fx.Int32)[0] * TOP
    rw = _p(RW, fx.Float32)[t * TOP + (tid < TOP).select(tid, fx.Int32(0))]
    gids = []
    for i in range_constexpr(NIT):
        j = tid + i * NT
        gids.append(_p(IDS, fx.Int32)[(j < R).select(j, fx.Int32(0))])
    zero4 = fx.Vector.filled(4, 0, fx.Int32)
    _st4(OUT, xb, zero4)
    _st4(OUT, xb + 4, zero4)
    if tid < 64:
        hall[tid] = fx.Int32(0)
        hbef[tid] = fx.Int32(0)

    # Local id of a global expert: the number of held experts below it (-1 when not held).
    bits = fx.Int64(rocdl.ballot(T.i64, _raw(held)))
    below = fx.Int32(fx.ctpop(bits & ((fx.Int64(1) << fx.Int64(lane)) - 1)))
    if lane == 0:
        wc[wave] = fx.Int32(fx.ctpop(bits))
    fx.gpu.barrier()
    base = fx.Int32(0)
    for w in range_constexpr(3):
        base = base + (wave > w).select(wc[w], fx.Int32(0))
    loc[tid] = held.select(below + base, fx.Int32(-1))
    fx.gpu.barrier()

    # Routes per local expert, over all tokens and over the tokens before t.
    for i in range_constexpr(NIT):
        j = tid + i * NT
        g = gids[i]
        ok = (j < R) & (j < nr) & (g >= 0) & (g < G)
        l = ok.select(loc[ok.select(g, fx.Int32(0))], fx.Int32(-1))
        itl[j] = l
        if l >= 0:
            _lds_add(hall, l, fx.Int32(1))
            if j < t * TOP:
                _lds_add(hbef, l, fx.Int32(1))
    fx.gpu.barrier()

    # First block of each local expert; boff[64] is the block count.
    if tid < 64:
        nbk = (hall[lane] + (BM - 1)) // BM
        incl = _dpp_intra_wave_prefix_sum(nbk, lane)
        boff[lane] = incl - nbk
        if lane == 63:
            boff[64] = incl
    fx.gpu.barrier()

    # This token's routes: sorted row = block start + routes of earlier tokens (and earlier slots).
    if tid < TOP:
        jj = t * TOP + tid
        l = itl[jj]
        lsafe = (l >= 0).select(l, fx.Int32(0))
        rank = hbef[lsafe]
        for k in range_constexpr(TOP - 1):
            rank = rank + ((tid > k) & (itl[t * TOP + k] == l)).select(fx.Int32(1), fx.Int32(0))
        p = (l >= 0).select(boff[lsafe] * BM + rank, fx.Int32(-1))
        pos[tid] = p
        if l >= 0:
            _p(SID, fx.Int32)[p] = (tid << 24) | t
            _p(SW, fx.Float32)[p] = rw
    fx.gpu.barrier()

    # MX-fp8 of row t: e8m0 = ceil_pow2(amax / the e4m3 max) over each 32 columns (a lane pair).
    ws = [x0[0], x0[1], x0[2], x0[3], x1[0], x1[1], x1[2], x1[3]]
    vals = []
    amax = fx.Int32(_AMAX_FLOOR_BITS)
    for w in ws:
        lo = w << 16
        hi = w & fx.Int32(-65536)
        vals.append(lo)
        vals.append(hi)
        alo = lo & 0x7FFFFFFF
        ahi = hi & 0x7FFFFFFF
        amax = (alo > amax).select(alo, amax)
        amax = (ahi > amax).select(ahi, amax)
    other = amax.shuffle_xor(fx.Int32(1), fx.Int32(64))
    amax = (other > amax).select(other, amax)
    u = (amax.bitcast(fx.Float32) * fx.Float32(1.0 / _FP8_E4M3_MAX)).bitcast(fx.Int32)
    ex = (u >> 23) & 255
    ex = ex + ((ex < 255) & ((u & 0x7FFFFF) != 0)).select(fx.Int32(1), fx.Int32(0))
    inv = ((254 - ex) << 23).bitcast(fx.Float32)
    words = []
    for q in range_constexpr(4):
        f = [vals[4 * q + r].bitcast(fx.Float32) * inv for r in range(4)]
        lo = rocdl.cvt_pk_fp8_f32(T.i32, _raw(f[0]), _raw(f[1]), _raw(fx.Int32(0)), False)
        wd = rocdl.cvt_pk_fp8_f32(T.i32, _raw(f[2]), _raw(f[3]), lo, True)
        words.append(fx.Int32(wd))
    _st4(A1, t * (D // 4) + tid * 4, fx.Vector.from_elements(words, fx.Int32))
    kc = tid >> 1
    if (tid & 1) == 0:
        sbyte = fx.Uint8(ex)
        for k in range_constexpr(TOP):
            p = pos[k]
            if p >= 0:
                # The stage-1 A-scale layout: 32-row tiles of D // 32 scale columns, preshuffled.
                addr = (
                    (p >> 5) * D
                    + (kc >> 3) * 256
                    + (kc & 3) * 64
                    + (p & 15) * 4
                    + ((kc >> 2) & 1) * 2
                    + ((p >> 4) & 1)
                )
                _p(A1S, fx.Uint8)[addr] = sbyte

    # Padding slots and block expert ids of the local experts t, t + M, ...
    for i in range_constexpr((E + M - 1) // M):
        e = t + i * M
        if e < E:
            c = hall[e]
            b0 = boff[e]
            nbk = (c + (BM - 1)) // BM
            if tid < nbk:
                _p(SEID, fx.Int32)[b0 + tid] = e
            s = c + tid
            if (tid < BM) & (s < nbk * BM):
                _p(SID, fx.Int32)[b0 * BM + s] = fx.Int32((TOP << 24) | M)
                _p(SW, fx.Float32)[b0 * BM + s] = fx.Float32(0.0)
    if (t == 0) & (tid == 0):
        _p(NV, fx.Int32)[0] = boff[64] * BM
        _p(NV, fx.Int32)[1] = fx.Int32(M)


def _build_stage2(
    *,
    model_dim: int,
    inter_dim: int,
    experts: int,
    topk: int,
    tile_m: int,
    tile_n: int,
    tile_k: int,
    b_nt: int,
    nw: int,
    k_rot: tuple,
):
    """Compile stage2 kernel (moe_gemm2): A2 @ W2.T -> [tokens, model_dim], atomic-add."""
    gpu_arch = get_rocm_arch()
    allocator = SmemAllocator(None, arch=gpu_arch, global_sym_name="smem0")
    scale_pack_m = 2
    scale_pack_n = 2
    scale_pack_k = 2
    pack_M = min(scale_pack_m, tile_m // 16)
    pack_N = min(scale_pack_n, tile_n // nw // 16)
    pack_K = min(scale_pack_k, tile_k // 128)
    cbsz = 0
    blgp = 4
    b_byte_div = 2
    b_stride_nlane = 16
    b_stride_klane = 16 * b_stride_nlane
    b_stride_k0 = 4 * b_stride_klane
    b_stride_n0 = inter_dim // b_byte_div // 64 * b_stride_k0
    assert model_dim % 16 == 0, "model_dim must be divisible by 16"
    expert_b_stride = model_dim // 16 * b_stride_n0
    out_elem_bytes = 2
    w_nbytes = experts * model_dim * inter_dim // b_byte_div
    scale_k_padded = (inter_dim + 255) // 256 * 256
    scale_kblk_padded = scale_k_padded // 32
    total_threads = 64 * nw
    bytes_per_thread_x = tile_m * tile_k // total_threads
    x_load_bytes = 16
    assert bytes_per_thread_x % x_load_bytes == 0
    num_x_loads = bytes_per_thread_x // x_load_bytes
    chunk_i32 = x_load_bytes // 4
    tile_k_dwords = tile_k // 4
    lds_stride = tile_k
    num_k_tiles_per_batch = int(inter_dim) // int(tile_k)
    k_rot_tag = "_".join(map(str, k_rot))
    module_name = f"mfma_moe2_t{tile_m}x{tile_n}x{tile_k}_nw{nw}_nt{b_nt}_kr{k_rot_tag}"
    lds_x_bytes = 2 * tile_m * lds_stride
    lds_out_bytes = 2 * tile_m * tile_n
    lds_total_bytes = max(lds_x_bytes, lds_out_bytes) + 2 * tile_m * 4
    lds_alloc_offset = allocator._align(allocator.ptr, 16)
    allocator.ptr = lds_alloc_offset + lds_total_bytes

    def _emit_moe_gemm2(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_sorted_weights: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_n_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
    ):
        tokens_in = arith.index_cast(ir.IndexType.get(), i32_tokens_in.ir_value())
        n_in = arith.index_cast(ir.IndexType.get(), i32_n_in.ir_value())
        k_in = arith.index_cast(ir.IndexType.get(), i32_k_in.ir_value())
        size_expert_ids_in = arith.index_cast(T.index, i32_size_expert_ids_in)
        x_elem = fx.Float8E4M3FN.ir_type
        f32 = T.f32
        i32 = T.i32
        i64 = T.i64
        vec4_f32 = T.vec(4, f32)
        vec16_x = T.vec(16, x_elem)
        vec2_i64 = T.vec(2, i64)

        def ptr_buffer_resource(ptr, num_records_bytes):
            addr = fx.ptrtoint(ptr)
            addr_i64 = arith.index_cast(T.i64, addr)
            return _bo_create_buffer_resource_from_addr(addr_i64, num_records_bytes=num_records_bytes)

        acc_init = arith.constant_vector(0.0, vec4_f32)
        kpack_bytes = 16
        c_k_orig = arith.constant(scale_k_padded, index=True)
        layout_scale = make_preshuffle_scale_layout(c_k=c_k_orig)
        shape_lds = fx.make_shape(tile_m, lds_stride)
        stride_lds = fx.make_stride(lds_stride, 1)
        layout_lds = fx.make_layout(shape_lds, stride_lds)
        tx = gpu.thread_id("x")
        by = gpu.block_id("x")
        bx_persist = gpu.block_id("y")
        k_blocks16 = arith.constant(tile_k // 16, index=True)
        layout_tx_wave_lane = fx.make_layout((nw, 64), stride=(64, 1))
        layout_lane16 = fx.make_layout((4, 16), stride=(16, 1))
        base_ptr = allocator.get_base()
        lds_x_ptr = SmemPtr(base_ptr, lds_alloc_offset, fx.Float8E4M3FN.ir_type, shape=(lds_total_bytes,))
        lds_x = lds_x_ptr.get()
        lds_out = SmemPtr(base_ptr, lds_x_ptr.byte_offset, T.bf16, shape=(tile_m * tile_n,)).get()
        lds_tid_off = max(lds_x_bytes, lds_out_bytes)
        lds_tid = SmemPtr(base_ptr, lds_x_ptr.byte_offset + lds_tid_off, T.i32, shape=(tile_m,)).get()
        lds_tw_off = lds_tid_off + int(tile_m) * 4
        lds_tw = SmemPtr(base_ptr, lds_x_ptr.byte_offset + lds_tw_off, T.f32, shape=(tile_m,)).get()
        c_topk = arith.constant(topk, index=True)
        x_nbytes_idx = tokens_in * c_topk * k_in
        x_nbytes_i32 = arith.index_cast(T.i32, x_nbytes_idx)
        x_rsrc = ptr_buffer_resource(arg_x, x_nbytes_i32)
        w_rsrc = ptr_buffer_resource(arg_w, w_nbytes)
        out_nbytes_idx = tokens_in * n_in * arith.constant(out_elem_bytes, index=True)
        out_nbytes_i32 = arith.index_cast(T.i32, out_nbytes_idx)
        out_rsrc = ptr_buffer_resource(arg_out, out_nbytes_i32)
        numids_rsrc = ptr_buffer_resource(arg_num_valid_ids, arith.constant(4, type=T.i32))
        num_valid_i32 = _bo_buffer_load(numids_rsrc, arith.constant(0, index=True), vec_width=1, dtype=T.i32)
        sorted_nbytes_idx = (
            size_expert_ids_in * arith.constant(tile_m, index=True) * arith.constant(4, index=True)
        )
        sorted_nbytes_i32 = arith.index_cast(T.i32, sorted_nbytes_idx)
        sorted_rsrc = ptr_buffer_resource(arg_sorted_token_ids, sorted_nbytes_i32)
        sorted_w_rsrc = ptr_buffer_resource(arg_sorted_weights, sorted_nbytes_i32)
        c_tm = arith.constant(tile_m, index=True)
        c1 = arith.constant(1, index=True)
        sort_blocks_ub = _div_pow2(size_expert_ids_in * c_tm + c_tm - c1, tile_m)
        eid_nbytes_idx = sort_blocks_ub * arith.constant(4, index=True)
        eid_nbytes_i32 = arith.index_cast(T.i32, eid_nbytes_idx)
        expert_rsrc = ptr_buffer_resource(arg_expert_ids, eid_nbytes_i32)
        bx_m_pre = bx_persist * arith.constant(tile_m, index=True)
        pre_expert = _bo_buffer_load(expert_rsrc, _div_pow2(bx_m_pre, tile_m), vec_width=1, dtype=T.i32)
        pre_first_tok = _bo_buffer_load(sorted_rsrc, bx_m_pre, vec_width=1, dtype=T.i32)
        layout_x_tile_div4 = fx.make_layout((tile_m, tile_k_dwords), stride=(tile_k_dwords, 1))
        tx_i32_base = tx * arith.constant(chunk_i32, index=True)
        pre_rows = []
        for i in range_constexpr(num_x_loads):
            row_local_pre, _ = tile_chunk_coord_i32(
                tx_i32_base=tx_i32_base,
                i=i,
                total_threads=total_threads,
                layout_tile_div4=layout_x_tile_div4,
                chunk_i32=chunk_i32,
            )
            pre_rows.append(_bo_buffer_load(sorted_rsrc, bx_m_pre + row_local_pre, vec_width=1, dtype=T.i32))
        pre_tid = _bo_buffer_load(sorted_rsrc, bx_m_pre + tx, vec_width=1, dtype=T.i32)
        pre_tw = _bo_buffer_load(sorted_w_rsrc, bx_m_pre + tx, vec_width=1, dtype=f32)
        rocdl.sched_barrier(0)
        num_valid_i32 = rocdl.ReadfirstlaneOp(T.i32, num_valid_i32).res
        num_valid_idx = arith.index_cast(ir.IndexType.get(), num_valid_i32)
        kblk = arith.constant(scale_kblk_padded, index=True)
        scale_rows = (
            (num_valid_idx + arith.constant(31, index=True))
            // arith.constant(32, index=True)
            * arith.constant(32, index=True)
        )
        sx_nbytes_idx = scale_rows * kblk
        sx_nbytes_i32 = arith.index_cast(T.i32, sx_nbytes_idx)
        sx_rsrc = ptr_buffer_resource(arg_scale_x, sx_nbytes_i32)
        kblk_w = arith.constant(scale_kblk_padded, index=True)
        mn_w = arith.constant(experts * model_dim, index=True)
        sw_nbytes_idx = mn_w * kblk_w
        sw_nbytes_i32 = arith.index_cast(T.i32, sw_nbytes_idx)
        sw_rsrc = ptr_buffer_resource(arg_scale_w, sw_nbytes_i32)
        c0_p = arith.constant(0, index=True)
        c1_p = arith.constant(1, index=True)
        init_prev_expert = arith.constant(0, type=T.i32)
        init_prev_b_base = arith.constant(0, index=True)
        for_persist = scf.ForOp(c0_p, c1_p, c1_p, [init_prev_expert, init_prev_b_base])
        for_ip = ir.InsertionPoint(for_persist.body)
        for_ip.__enter__()
        mi_p = for_persist.induction_variable
        prev_expert_i32 = for_persist.inner_iter_args[0]
        prev_expert_b_base = for_persist.inner_iter_args[1]
        bx = bx_persist + mi_p
        bx_m = bx * arith.constant(tile_m, index=True)
        bx_m_i32 = arith.index_cast(T.i32, bx_m)
        blk_valid = arith.cmpi(CmpIPredicate.ult, bx_m_i32, num_valid_i32)
        expert_i32 = pre_expert
        expert_idx = arith.index_cast(T.index, expert_i32)
        exp_valid = arith.cmpi(CmpIPredicate.ult, expert_i32, arith.constant(experts, type=T.i32))
        delta_expert = arith.subi(expert_i32, prev_expert_i32)
        delta_expert_idx = arith.index_cast(ir.IndexType.get(), delta_expert)
        delta_b = delta_expert_idx * arith.constant(expert_b_stride, index=True)
        expert_b_base = prev_expert_b_base + delta_b
        first_tok = pre_first_tok
        first_tid = arith.andi(first_tok, arith.constant(16777215, type=T.i32))
        tokens_i32_guard = arith.index_cast(T.i32, tokens_in)
        tile_has_tokens = arith.cmpi(CmpIPredicate.ult, first_tid, tokens_i32_guard)
        if const_expr(pack_M < scale_pack_m):
            m_off = _mod_pow2(_div_pow2(bx_m, 16), scale_pack_m)
            m_scale_shift_i32 = arith.index_cast(T.i32, m_off * arith.constant(8, index=True))
        else:
            m_scale_shift_i32 = None

        def moe_gemm2_then_body():
            body_tile_n = tile_n
            n_idx = arith.constant(model_dim, index=True)
            expert_off_idx = expert_idx * n_idx

            def mixed_b_mfma(a128, b128, acc, opsel_a, a_scale_val, opsel_b, b_scale_val):
                return rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                    vec4_f32, [a128, b128, acc, cbsz, blgp, opsel_a, a_scale_val, opsel_b, b_scale_val]
                )

            vec4_i32 = T.vec(4, i32)
            c_k_div4 = _div_pow2(k_in, 4)
            topk_i32 = arith.constant(topk)
            mask24 = arith.constant(16777215)
            tokens_i32 = arith.index_cast(T.i32, tokens_in)

            def x_tile_chunk_coord_i32(i: int):
                return tile_chunk_coord_i32(
                    tx_i32_base=tx_i32_base,
                    i=i,
                    total_threads=total_threads,
                    layout_tile_div4=layout_x_tile_div4,
                    chunk_i32=chunk_i32,
                )

            def load_x(idx_i32):
                return _buffer_load_vec(
                    x_rsrc, idx_i32, elem_type=x_elem, vec_elems=16, offset_in_bytes=False
                )

            x_row_base_div4 = []
            x_col_local_i32 = []
            x_row_local = []
            for i in range_constexpr(num_x_loads):
                row_local, col_local_i32 = x_tile_chunk_coord_i32(i)
                x_row_local.append(row_local)
                x_col_local_i32.append(col_local_i32)
                fused_i = pre_rows[i]
                t_i32 = arith.andi(fused_i, mask24)
                s_i32 = arith.shrui(fused_i, arith.constant(24))
                t_valid = arith.cmpi(CmpIPredicate.ult, t_i32, tokens_i32)
                s_valid = arith.cmpi(CmpIPredicate.ult, s_i32, topk_i32)
                ts_valid = arith.andi(t_valid, s_valid)
                t_safe = arith.select(ts_valid, t_i32, arith.constant(0))
                s_safe = arith.select(ts_valid, s_i32, arith.constant(0))
                row_ts_i32 = t_safe * topk_i32 + s_safe
                row_ts_idx = arith.index_cast(T.index, row_ts_i32)
                x_row_base_div4.append(row_ts_idx * c_k_div4)

            def load_x_tile(base_k):
                base_k_div4 = _div_pow2(base_k, 4)
                parts = []
                for i in range_constexpr(num_x_loads):
                    idx_i32 = x_row_base_div4[i] + base_k_div4 + x_col_local_i32[i]
                    x_vec = load_x(idx_i32)
                    parts.append(_vec_bitcast(vec4_i32, x_vec))
                return parts

            coord_wl = idx2crd(fx.Int32(tx), layout_tx_wave_lane)
            wave_id = get(coord_wl, 0)
            lane_id = get(coord_wl, 1)
            coord_l16 = idx2crd(fx.Int32(lane_id), layout_lane16)
            lane_div_16 = get(coord_l16, 0)
            lane_mod_16 = get(coord_l16, 1)
            row_a_lds = lane_mod_16
            col_offset_base = lane_div_16 * arith.constant(16, index=True)
            num_waves = nw
            body_n_per_wave = body_tile_n // num_waves
            body_num_acc_n = body_n_per_wave // 16
            c_n_per_wave = arith.constant(body_n_per_wave, index=True)
            wave_mod_4 = _mod_pow2(wave_id, nw)
            n_tile_base = wave_mod_4 * c_n_per_wave
            body_by_n = by * arith.constant(tile_n, index=True)
            if const_expr(pack_N < scale_pack_n):
                global_n_base = expert_off_idx + body_by_n + n_tile_base
                n_off = _mod_pow2(_div_pow2(global_n_base, 16), scale_pack_n)
                n_scale_shift_i32 = arith.index_cast(T.i32, n_off * arith.constant(8, index=True))
            else:
                n_scale_shift_i32 = None
            n_intra_list = [None] * body_num_acc_n
            n_blk_list = [None] * body_num_acc_n
            for i in range_constexpr(body_num_acc_n):
                offset = i * 16
                c_offset = arith.constant(offset, index=True)
                global_n = body_by_n + n_tile_base + c_offset + lane_mod_16
                n_blk_list[i] = _div_pow2(global_n, 16)
                n_intra_list[i] = _mod_pow2(global_n, 16)
            m_repeat = tile_m // 16
            k_unroll = tile_k // 128
            k_unroll_packed = k_unroll // pack_K
            m_repeat_packed = m_repeat // pack_M
            num_acc_n_packed = body_num_acc_n // pack_N

            def load_b_packs_k64(base_k, ku: int, ni: int):
                """One B MFMA k-step: a single 16-byte fp4 load, as the two i64 of the MFMA's lower half."""
                routed_k0_base = _div_pow2(base_k, 64) + arith.constant(ku, index=True)
                idx_pack = (
                    expert_b_base
                    + n_blk_list[ni] * arith.constant(b_stride_n0, index=True)
                    + routed_k0_base * arith.constant(b_stride_k0, index=True)
                    + lane_div_16 * arith.constant(b_stride_klane, index=True)
                    + n_intra_list[ni] * arith.constant(b_stride_nlane, index=True)
                )
                b16 = _buffer_load_vec(
                    w_rsrc,
                    idx_pack,
                    elem_type=T.i8,
                    vec_elems=kpack_bytes,
                    offset_in_bytes=True,
                    cache_modifier=b_nt,
                )
                b_i64x2 = _vec_bitcast(vec2_i64, b16)
                return (_vec_extract(b_i64x2, 0), _vec_extract(b_i64x2, 1))

            def accum_b_ku(b_tile, base_k, ku):
                packs0, packs1 = ([], [])
                for ni in range_constexpr(body_num_acc_n):
                    b = load_b_packs_k64(base_k, ku, ni)
                    packs0.append(b[0])
                    packs1.append(b[1])
                b_tile.append((packs0, packs1))

            def load_b_tile(base_k):
                b_tile = []
                for ku in range_constexpr(k_unroll):
                    accum_b_ku(b_tile, base_k, ku)
                return b_tile

            b_split_enabled = k_unroll >= 2
            b_split_ku = k_unroll // 2 if b_split_enabled else k_unroll

            def load_b_tile_lo(base_k):
                b_tile = []
                for ku in range_constexpr(b_split_ku):
                    accum_b_ku(b_tile, base_k, ku)
                return b_tile

            def load_b_tile_hi(base_k):
                b_tile = []
                for ku in range_constexpr(b_split_ku, k_unroll):
                    accum_b_ku(b_tile, base_k, ku)
                return b_tile

            def load_scale(rsrc, scale_info, ku, mni):
                k_lane = lane_div_16
                n_lane = lane_mod_16
                idx_pack = (
                    mni * scale_info.stride_n0
                    + ku * scale_info.stride_k0
                    + k_lane * scale_info.stride_klane
                    + n_lane
                )
                s = _bo_buffer_load(rsrc, idx_pack, vec_width=1, dtype=T.i32)
                return _vec_from_elements(T.vec(1, T.i32), [s])

            def apply_k_shift(scale_vec, k_shift_bits):
                if const_expr(k_shift_bits > 0):
                    val = _vec_extract(scale_vec, 0)
                    val = arith.shrui(val, arith.constant(k_shift_bits, type=T.i32))
                    return _vec_from_elements(T.vec(1, T.i32), [val])
                return scale_vec

            def load_b_scale_tile(base_k, k_shift_bits=0):
                b_scale_tile = []
                for ku in range_constexpr(k_unroll_packed):
                    for ni in range_constexpr(num_acc_n_packed):
                        scale = load_scale(
                            sw_rsrc,
                            layout_scale,
                            ku + base_k,
                            ni
                            + _div_pow2(
                                _div_pow2(expert_off_idx + body_by_n + n_tile_base, scale_pack_n), 16
                            ),
                        )
                        scale = apply_k_shift(scale, k_shift_bits)
                        b_scale_tile.append(scale)
                return b_scale_tile

            def load_a_scale_tile(base_k, k_shift_bits=0):
                a_scale_tile = []
                for ku in range_constexpr(k_unroll_packed):
                    for mi in range_constexpr(m_repeat_packed):
                        scale = load_scale(
                            sx_rsrc,
                            layout_scale,
                            ku + base_k,
                            mi + _div_pow2(_div_pow2(bx_m, scale_pack_m), 16),
                        )
                        scale = apply_k_shift(scale, k_shift_bits)
                        a_scale_tile.append(scale)
                return a_scale_tile

            def prefetch_ab_scale_tile(base_k, k_shift_bits=0):
                return [load_a_scale_tile(base_k, k_shift_bits), load_b_scale_tile(base_k, k_shift_bits)]

            def store_x_tile_to_lds(vec_x_in_parts, lds_base):
                for i in range_constexpr(num_x_loads):
                    row_local = x_row_local[i]
                    col_local_i32 = x_col_local_i32[i]
                    lds_store_16b_xor16(
                        lds_memref=lds_x,
                        vec16_ty=vec16_x,
                        layout_lds=layout_lds,
                        row_local=row_local,
                        col_local_i32=col_local_i32,
                        k_blocks16=k_blocks16,
                        lds_base=lds_base,
                        vec_part=vec_x_in_parts[i],
                    )

            def lds_load_packs_k64(curr_row_a_lds, col_base, lds_base):
                col_base_swz = swizzle_xor16(curr_row_a_lds, col_base, k_blocks16)
                idx_a16 = crd2idx([fx.Int32(curr_row_a_lds), fx.Int32(col_base_swz)], layout_lds)
                idx_a16 = idx_a16 + lds_base
                loaded_a16 = _vec_load_op(vec16_x, lds_x, [idx_a16])
                a_i64x2 = _vec_bitcast(vec2_i64, loaded_a16)
                a0 = _vec_extract(a_i64x2, 0)
                a1 = _vec_extract(a_i64x2, 1)
                return (a0, a1)

            def compute_tile(
                acc_in,
                b_tile_in,
                lds_base,
                a_scale,
                b_scale,
                *,
                prefetch_epilogue: bool = False,
                a0_prefetch=None,
                a1_prefetch=None,
                b_hi_loader=None,
            ):
                if const_expr(b_hi_loader is not None):
                    b_tile_full = [None] * k_unroll
                    for i in range_constexpr(b_split_ku):
                        b_tile_full[i] = b_tile_in[i]
                else:
                    b_tile_full = b_tile_in
                acc_list = list(acc_in)
                tw_pf = None
                if const_expr(prefetch_epilogue):
                    tw_pf = []
                    lane_div_16_mul4_pf = lane_div_16 * arith.index(4)
                    vec4_f32_pf = T.vec(4, f32)
                    for mi in range_constexpr(m_repeat):
                        mi_base_pf = arith.constant(mi * 16, index=True)
                        lds_row_pf = mi_base_pf + lane_div_16_mul4_pf
                        tw_v4 = _vec_load_op(vec4_f32_pf, lds_tw, [lds_row_pf])
                        for ii in range_constexpr(4):
                            tw_pf.append(_vec_extract(tw_v4, ii))
                c0_i64 = arith.constant(0, type=T.i64)
                vec4_i64 = T.vec(4, T.i64)
                vec8_i32 = T.vec(8, T.i32)

                def pack_i64x4_to_i32x8(x0, x1, x2, x3):
                    v4 = _vec_from_elements(vec4_i64, [x0, x1, x2, x3])
                    return _vec_bitcast(vec8_i32, v4)

                pack_K_shift = (pack_K - 1).bit_length()
                pack_K_mask = pack_K - 1
                if const_expr(b_hi_loader is not None):
                    b_hi = b_hi_loader()
                    for bhi_i in range_constexpr(len(b_hi)):
                        b_tile_full[b_split_ku + bhi_i] = b_hi[bhi_i]
                rocdl.s_setprio(1)
                for k_idx in range_constexpr(k_unroll):
                    ku128 = k_idx >> pack_K_shift
                    ikxdl = k_idx & pack_K_mask
                    b_packs0, b_packs1 = b_tile_full[k_idx]
                    col_base = col_offset_base + k_idx * 128
                    for mi in range_constexpr(m_repeat_packed):
                        a_scale_i32 = a_scale[ku128 * m_repeat_packed + mi]
                        a_scale_val = _vec_extract(a_scale_i32, 0)
                        if const_expr(m_scale_shift_i32 is not None):
                            a_scale_val = arith.shrui(a_scale_val, m_scale_shift_i32)
                        a128_list = [None] * pack_M
                        for imxdl in range_constexpr(pack_M):
                            col_base0 = col_base
                            mi_idx = mi * pack_M + imxdl
                            mi_val = arith.constant(mi_idx * 16, index=True)
                            curr_row_a_lds = row_a_lds + mi_val
                            if const_expr(a0_prefetch is not None and k_idx == 0 and (mi_idx == 0)):
                                a0, a1 = a0_prefetch
                            elif const_expr(a1_prefetch is not None and k_idx == 1 and (mi_idx == 0)):
                                a0, a1 = a1_prefetch
                            else:
                                a0, a1 = lds_load_packs_k64(curr_row_a_lds, col_base0, lds_base)
                            col_base1 = col_base + 64
                            a2, a3 = lds_load_packs_k64(curr_row_a_lds, col_base1, lds_base)
                            a128_list[imxdl] = pack_i64x4_to_i32x8(a0, a1, a2, a3)
                        for ni in range_constexpr(num_acc_n_packed):
                            b_scale_i32 = b_scale[ku128 * num_acc_n_packed + ni]
                            b_scale_val = _vec_extract(b_scale_i32, 0)
                            if const_expr(n_scale_shift_i32 is not None):
                                b_scale_val = arith.shrui(b_scale_val, n_scale_shift_i32)
                            b128_list = [None] * pack_N
                            for inxdl in range_constexpr(pack_N):
                                ni_idx = ni * pack_N + inxdl
                                b128_list[inxdl] = pack_i64x4_to_i32x8(
                                    b_packs0[ni_idx], b_packs1[ni_idx], c0_i64, c0_i64
                                )
                            for imxdl in range_constexpr(pack_M):
                                mi_idx = mi * pack_M + imxdl
                                a128 = a128_list[imxdl]
                                for inxdl in range_constexpr(pack_N):
                                    ni_idx = ni * pack_N + inxdl
                                    b128 = b128_list[inxdl]
                                    acc_idx = mi_idx * body_num_acc_n + ni_idx
                                    acc_list[acc_idx] = mixed_b_mfma(
                                        a128,
                                        b128,
                                        acc_list[acc_idx],
                                        ikxdl * scale_pack_m + imxdl,
                                        a_scale_val,
                                        ikxdl * scale_pack_n + inxdl,
                                        b_scale_val,
                                    )
                return (acc_list, tw_pf)

            lds_tile_elems = arith.constant(tile_m * lds_stride, index=True)
            lds_base_cur = arith.index(0)
            lds_base_nxt = lds_tile_elems
            rocdl.sched_barrier(0)

            def k_shift_bits(k_py):
                if const_expr(pack_K >= scale_pack_k):
                    return 0
                return k_py // 128 % scale_pack_k * scale_pack_m * 8

            def k_base(k_py):
                return k_py // scale_pack_k // 128

            rot_unit = int(tile_k) * (scale_pack_k if pack_K < scale_pack_k else 1)
            rot_units = int(inter_dim) // rot_unit
            rot_by, rot_bx, rot_sh = k_rot
            rot_v = by * arith.constant(rot_by, index=True)
            if const_expr(rot_bx):
                rot_v = rot_v + _div_pow2(bx, 1 << rot_sh) * arith.constant(rot_bx, index=True)
            rot_u = _mod_pow2(rot_v, rot_units)

            def rk(k_py):
                return _mod_pow2(
                    rot_u * arith.constant(rot_unit, index=True) + arith.constant(k_py, index=True),
                    int(inter_dim),
                )

            def rkb(k_py):
                return _mod_pow2(
                    rot_u * arith.constant(rot_unit // (scale_pack_k * 128), index=True)
                    + arith.constant(k_base(k_py), index=True),
                    int(inter_dim) // (scale_pack_k * 128),
                )

            row_stride_bytes = int(model_dim) * int(out_elem_bytes)
            c_tile_m_idx = arith.constant(tile_m, index=True)
            tid_in_range = arith.cmpi(CmpIPredicate.ult, tx, c_tile_m_idx)

            def emit_tid_lds_prologue():
                if_tid = scf.IfOp(tid_in_range)
                with ir.InsertionPoint(if_tid.then_block):
                    tid_row = bx_m + tx
                    tid_val = pre_tid
                    tw_val_m = pre_tw
                    t_pre = tid_val & arith.constant(16777215, type=T.i32)
                    s_pre = arith.shrui(tid_val, arith.constant(24, type=T.i32))
                    row_byte_off = t_pre * arith.constant(row_stride_bytes, type=T.i32)
                    global_row_i32 = arith.index_cast(T.i32, tid_row)
                    valid = arith.andi(
                        arith.andi(
                            arith.cmpi(CmpIPredicate.ult, global_row_i32, num_valid_i32),
                            arith.cmpi(CmpIPredicate.ult, t_pre, tokens_i32_guard),
                        ),
                        arith.cmpi(CmpIPredicate.ult, s_pre, arith.constant(topk, type=T.i32)),
                    )
                    stored_val = arith.select(valid, row_byte_off, arith.constant(2147418112, type=T.i32))
                    tid_vec1 = _vec_from_elements(T.vec(1, T.i32), [stored_val])
                    _vec_store(tid_vec1, lds_tid, [tx])
                    tw_vec1 = _vec_from_elements(T.vec(1, T.f32), [tw_val_m])
                    _vec_store(tw_vec1, lds_tw, [tx], alignment=4)
                    scf.YieldOp([])

            emit_tid_lds_prologue()
            k0 = rk(0)
            k0_bk = k0 // b_byte_div
            if const_expr(b_split_enabled):
                b_cur = load_b_tile_lo(k0_bk)
            else:
                b_cur = load_b_tile(k0_bk)
            a_scale_pong, b_scale_pong = prefetch_ab_scale_tile(rkb(0), k_shift_bits(0))
            rocdl.sched_barrier(0)
            x_regs0 = load_x_tile(k0)
            store_x_tile_to_lds(x_regs0, lds_base_cur)
            gpu.barrier()
            acc = [acc_init] * body_num_acc_n * m_repeat
            lds_base_pong = lds_base_cur
            lds_base_ping = lds_base_nxt
            a0_prefetch_pong = lds_load_packs_k64(row_a_lds, col_offset_base, lds_base_pong)
            a1_col_base = col_offset_base + 128
            a1_prefetch_pong = (
                lds_load_packs_k64(row_a_lds, a1_col_base, lds_base_pong) if pack_K >= 2 else None
            )
            assert num_k_tiles_per_batch % 2 == 0 and num_k_tiles_per_batch >= 4
            k_main2_py = (num_k_tiles_per_batch - 2) * int(tile_k)
            b_pong = b_cur
            k0_pong_bk = k0_bk

            def make_b_hi_loader(base_k):
                return lambda bk=base_k: load_b_tile_hi(bk)

            for k_iv_py in range_constexpr(0, k_main2_py, tile_k * 2):
                next_k1_py = k_iv_py + tile_k
                next_k1 = rk(next_k1_py)
                next_k1_bk = next_k1 // b_byte_div
                x_regs_ping = load_x_tile(next_k1)
                a_scale_ping, b_scale_ping = prefetch_ab_scale_tile(rkb(next_k1_py), k_shift_bits(next_k1_py))
                b_ping_lo = load_b_tile_lo(next_k1_bk) if b_split_enabled else load_b_tile(next_k1_bk)
                acc, _ = compute_tile(
                    acc,
                    b_pong,
                    lds_base_pong,
                    a_scale_pong,
                    b_scale_pong,
                    a0_prefetch=a0_prefetch_pong,
                    a1_prefetch=a1_prefetch_pong,
                    b_hi_loader=make_b_hi_loader(k0_pong_bk) if b_split_enabled else None,
                )
                store_x_tile_to_lds(x_regs_ping, lds_base_ping)
                gpu.barrier()
                a0_prefetch_ping = lds_load_packs_k64(row_a_lds, col_offset_base, lds_base_ping)
                a1_prefetch_ping = (
                    lds_load_packs_k64(row_a_lds, a1_col_base, lds_base_ping) if pack_K >= 2 else None
                )
                next_k2_py = k_iv_py + tile_k * 2
                next_k2 = rk(next_k2_py)
                next_k2_bk = next_k2 // b_byte_div
                x_regs_pong = load_x_tile(next_k2)
                a_scale_pong, b_scale_pong = prefetch_ab_scale_tile(rkb(next_k2_py), k_shift_bits(next_k2_py))
                b_pong = load_b_tile_lo(next_k2_bk) if b_split_enabled else load_b_tile(next_k2_bk)
                acc, _ = compute_tile(
                    acc,
                    b_ping_lo,
                    lds_base_ping,
                    a_scale_ping,
                    b_scale_ping,
                    a0_prefetch=a0_prefetch_ping,
                    a1_prefetch=a1_prefetch_ping,
                    b_hi_loader=make_b_hi_loader(next_k1_bk) if b_split_enabled else None,
                )
                k0_pong_bk = next_k2_bk
                store_x_tile_to_lds(x_regs_pong, lds_base_pong)
                gpu.barrier()
                a0_prefetch_pong = lds_load_packs_k64(row_a_lds, col_offset_base, lds_base_pong)
                a1_prefetch_pong = (
                    lds_load_packs_k64(row_a_lds, a1_col_base, lds_base_pong) if pack_K >= 2 else None
                )
            k_tail1_py = (int(inter_dim) + tile_k - 1) // tile_k * tile_k - tile_k
            k_tail1 = rk(k_tail1_py)
            k_tail1_bk = k_tail1 // b_byte_div
            x_regs_ping = load_x_tile(k_tail1)
            b_ping_lo = load_b_tile_lo(k_tail1_bk) if b_split_enabled else load_b_tile(k_tail1_bk)
            a_scale_ping, b_scale_ping = prefetch_ab_scale_tile(rkb(k_tail1_py), k_shift_bits(k_tail1_py))
            acc, _ = compute_tile(
                acc,
                b_pong,
                lds_base_pong,
                a_scale_pong,
                b_scale_pong,
                a0_prefetch=a0_prefetch_pong,
                a1_prefetch=a1_prefetch_pong,
                b_hi_loader=make_b_hi_loader(k0_pong_bk) if b_split_enabled else None,
            )
            store_x_tile_to_lds(x_regs_ping, lds_base_ping)
            gpu.barrier()
            a0_prefetch_ping = lds_load_packs_k64(row_a_lds, col_offset_base, lds_base_ping)
            a1_prefetch_ping = (
                lds_load_packs_k64(row_a_lds, a1_col_base, lds_base_ping) if pack_K >= 2 else None
            )
            acc, epilogue_pf = compute_tile(
                acc,
                b_ping_lo,
                lds_base_ping,
                a_scale_ping,
                b_scale_ping,
                a0_prefetch=a0_prefetch_ping,
                a1_prefetch=a1_prefetch_ping,
                prefetch_epilogue=True,
                b_hi_loader=make_b_hi_loader(k_tail1_bk) if b_split_enabled else None,
            )
            tw_pf = epilogue_pf
            zero_i32 = arith.constant(0)

            def write_row_to_lds(*, mi: int, ii: int, row_base_lds, col_base_local, num_acc_n: int, lds_out):
                tw = tw_pf[mi * 4 + ii]
                for ni in range_constexpr(num_acc_n):
                    col_local = col_base_local + ni * 16
                    acc_idx = mi * num_acc_n + ni
                    v = _vec_extract(acc[acc_idx], ii)
                    v = v * tw
                    v_out = arith.trunc_f(T.bf16, v)
                    lds_idx = row_base_lds + col_local
                    vec1_out = T.vec(1, T.bf16)
                    v1 = _vec_from_elements(vec1_out, [v_out])
                    _vec_store(v1, lds_out, [lds_idx], alignment=2)

            out_elem_bytes_i32 = arith.constant(int(out_elem_bytes), type=T.i32)

            def precompute_row(*, row_local, row):
                row_byte_off_i32 = memref.load(lds_tid, [row_local])
                return (row_byte_off_i32, None)

            def store_pair(*, row, row_ctx, col_g0, frag):
                col_i32 = arith.index_cast(T.i32, col_g0)
                col_byte_off_i32 = col_i32 * out_elem_bytes_i32
                byte_off_i32 = row_ctx + col_byte_off_i32
                rocdl.raw_ptr_buffer_atomic_fadd(frag, out_rsrc, byte_off_i32, zero_i32, zero_i32)

            rocdl.s_setprio(3)
            c_shuffle_epilog(
                tile_m=tile_m,
                tile_n=body_tile_n,
                e_vec=2,
                block_size=total_threads,
                m_repeat=m_repeat,
                num_acc_n=body_num_acc_n,
                tx=tx,
                lane_div_16=lane_div_16,
                lane_mod_16=lane_mod_16,
                bx_m=bx_m,
                by_n=body_by_n,
                n_tile_base=n_tile_base,
                lds_out=lds_out,
                frag_elem_type=ir.BF16Type.get(),
                write_row_to_lds=write_row_to_lds,
                precompute_row=precompute_row,
                store_pair=store_pair,
            )
            rocdl.s_setprio(0)

        all_valid = arith.andi(blk_valid, arith.andi(exp_valid, tile_has_tokens))
        if_valid = scf.IfOp(all_valid)
        with ir.InsertionPoint(if_valid.then_block):
            moe_gemm2_then_body()
            scf.YieldOp([])
        gpu.barrier()
        scf.YieldOp([expert_i32, expert_b_base])
        for_ip.__exit__(None, None, None)

    @flyc.kernel(name=module_name)
    def moe_gemm2(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_sorted_weights: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_n_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
    ):
        _emit_moe_gemm2(
            arg_out,
            arg_x,
            arg_w,
            arg_scale_x,
            arg_scale_w,
            arg_sorted_token_ids,
            arg_expert_ids,
            arg_sorted_weights,
            arg_num_valid_ids,
            i32_tokens_in,
            i32_n_in,
            i32_k_in,
            i32_size_expert_ids_in,
        )

    cache_tag = module_name

    def _launch_mixed_moe_gemm2(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_sorted_weights: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_n_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
        stream: fx.Stream,
    ):
        # Read so that the JIT cache key, which sees closure values, covers the configuration.
        _ = cache_tag
        allocator.finalized = False
        ctx = CompilationContext.get_current()
        with ir.InsertionPoint(ctx.gpu_module_body):
            allocator.finalize()
        n_in = arith.index_cast(ir.IndexType.get(), i32_n_in.ir_value())
        tile_n_idx = arith.constant(tile_n, index=True)
        gx = (n_in + tile_n_idx - arith.constant(1, index=True)) // tile_n_idx
        gy = arith.index_cast(ir.IndexType.get(), i32_size_expert_ids_in.ir_value())
        launcher = moe_gemm2(
            arg_out,
            arg_x,
            arg_w,
            arg_scale_x,
            arg_scale_w,
            arg_sorted_token_ids,
            arg_expert_ids,
            arg_sorted_weights,
            arg_num_valid_ids,
            i32_tokens_in,
            i32_n_in,
            i32_k_in,
            i32_size_expert_ids_in,
        )
        launcher.launch(grid=(gx, gy, 1), block=(total_threads, 1, 1), stream=stream)

    @flyc.jit
    def launch_mixed_moe_gemm2(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_sorted_weights: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_n_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
        execute: fx.Int32,
        stream: fx.Stream,
    ):
        if execute != 0:
            _launch_mixed_moe_gemm2(
                arg_out,
                arg_x,
                arg_w,
                arg_scale_x,
                arg_scale_w,
                arg_sorted_token_ids,
                arg_expert_ids,
                arg_sorted_weights,
                arg_num_valid_ids,
                i32_tokens_in,
                i32_n_in,
                i32_k_in,
                i32_size_expert_ids_in,
                stream,
            )

    return launch_mixed_moe_gemm2


def _build_stage1(
    *,
    model_dim: int,
    inter_dim: int,
    experts: int,
    topk: int,
    tile_m: int,
    tile_n: int,
    tile_k: int,
    waves_per_eu: int,
    b_nt: int,
):
    """Compile stage1 kernel: silu(X @ W_gate.T) * (X @ W_up.T), gate/up interleaved, quantized to MX-fp8."""
    gpu_arch = get_rocm_arch()
    allocator_pong = SmemAllocator(None, arch=gpu_arch, global_sym_name="smem0")
    allocator_ping = SmemAllocator(None, arch=gpu_arch, global_sym_name="smem1")
    sort_block_m = tile_m
    num_waves = min(4, tile_n // 32)
    total_threads = num_waves * 64
    pack_M = 1 if tile_m < 32 else 2
    n_per_wave = tile_n // num_waves
    pack_N = min(2, n_per_wave // 16)
    pack_K = 2
    scale_mn_pack = 2
    assert pack_N == scale_mn_pack
    cbsz = 0
    blgp = 4
    b_byte_div = 2
    bytes_per_thread_x = tile_m * tile_k // total_threads
    assert bytes_per_thread_x % 16 == 0
    num_x_loads = bytes_per_thread_x // 16
    tile_k_dwords = tile_k // 4
    lds_stride = tile_k
    module_name = f"mfma_moe1_t{tile_m}x{tile_n}x{tile_k}"
    single_x_bytes = tile_m * tile_k
    lds_out_bytes = 4 * tile_m * tile_n
    lds_tid_bytes = tile_m * 4
    pong_buffer_bytes = max(single_x_bytes, lds_out_bytes)
    ping_buffer_bytes = single_x_bytes
    lds_pong_offset = allocator_pong._align(allocator_pong.ptr, 16)
    allocator_pong.ptr = lds_pong_offset + pong_buffer_bytes
    lds_tid_offset_pong = allocator_pong._align(allocator_pong.ptr, 4)
    allocator_pong.ptr = lds_tid_offset_pong + lds_tid_bytes
    lds_ping_offset = allocator_ping._align(allocator_ping.ptr, 16)
    allocator_ping.ptr = lds_ping_offset + ping_buffer_bytes
    # Pad the LDS so that at most waves_per_eu workgroups fit on a CU.
    total_cu_lds = 160 * 1024
    min_lds = total_cu_lds // (waves_per_eu + 1) + 1
    pong_sz = allocator_pong._align(allocator_pong.ptr, 128)
    ping_sz = allocator_ping._align(allocator_ping.ptr, 128)
    cur_lds = pong_sz + ping_sz
    if cur_lds < min_lds:
        allocator_ping.ptr += min_lds - cur_lds
    kpack_bytes = 16
    w_nbytes = experts * (2 * inter_dim) * model_dim // b_byte_div
    e_vec_s1 = max(2, min(tile_n // 32, 8))
    assert e_vec_s1 == 2, "the fp8 store writes one 2-byte pair"
    num_threads_per_quant_blk_s1 = 32 // e_vec_s1
    shuffle_dists_s1 = []
    sh_val = 1
    while sh_val < num_threads_per_quant_blk_s1:
        shuffle_dists_s1.append(sh_val)
        sh_val *= 2
    num_shuffle_steps_s1 = len(shuffle_dists_s1)
    pipe_m_repeat = tile_m // 16
    pipe_k_unroll = tile_k // 128
    pipe_k_unroll_packed = pipe_k_unroll // pack_K
    pipe_num_acc_n = n_per_wave // 16
    pipe_a_groups = [
        [(k, mi), (k + 1, mi)] for mi in range(pipe_m_repeat) for k in range(0, pipe_k_unroll, 2)
    ]
    pipe_b_loads = [(ku, ni) for ku in range(pipe_k_unroll) for ni in range(pipe_num_acc_n)]
    pipe_num_acc_n_packed = pipe_num_acc_n // pack_N
    pipe_all_mfma = []
    for ku128 in range(pipe_k_unroll_packed):
        for ni_packed in range(pipe_num_acc_n_packed):
            for ikxdl in range(pack_K):
                for inxdl in range(pack_N):
                    k_idx = ku128 * pack_K + ikxdl
                    ni_idx = ni_packed * pack_N + inxdl
                    pipe_all_mfma.append((k_idx, ni_idx, ikxdl, inxdl, ku128))
    pipe_mfma_per_phase = max(1, len(pipe_all_mfma) // 4)
    pipe_n_phases = len(pipe_all_mfma) // pipe_mfma_per_phase
    a_groups_per_phase = (len(pipe_a_groups) + pipe_n_phases - 1) // pipe_n_phases
    pipe_phases = []
    mfma_i = 0
    a_i = 0
    for _p in range(pipe_n_phases):
        a_reads = []
        for _ in range(a_groups_per_phase):
            if a_i < len(pipe_a_groups):
                a_reads.extend(pipe_a_groups[a_i])
                a_i += 1
        phase = {
            "mfma": pipe_all_mfma[mfma_i : mfma_i + pipe_mfma_per_phase],
            "a_reads": a_reads,
            "b_loads": [],
            "has_scale": _p == 0,
        }
        mfma_i += pipe_mfma_per_phase
        pipe_phases.append(phase)
    bi = 0
    for _p in range(1, pipe_n_phases):
        rem_b = len(pipe_b_loads) - bi
        rem_p = pipe_n_phases - _p
        n_b = (rem_b + rem_p - 1) // rem_p if rem_p > 0 else 0
        for _ in range(n_b):
            if bi < len(pipe_b_loads):
                pipe_phases[_p]["b_loads"].append(pipe_b_loads[bi])
                bi += 1
    pp_mfma = [p["mfma"] for p in pipe_phases]
    pp_a_reads = [p["a_reads"] for p in pipe_phases]
    pp_b_loads = [p["b_loads"] for p in pipe_phases]
    pp_has_scale = [p["has_scale"] for p in pipe_phases]

    def _emit_moe_gemm1(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        arg_out_scale_sorted: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
        f32_swiglu_limit: fx.Float32,
    ):
        tokens_in = arith.index_cast(ir.IndexType.get(), i32_tokens_in.ir_value())
        k_in = arith.index_cast(ir.IndexType.get(), i32_k_in.ir_value())
        size_expert_ids_in = arith.index_cast(ir.IndexType.get(), i32_size_expert_ids_in.ir_value())
        swiglu_neg_limit = -f32_swiglu_limit
        x_elem = fx.Float8E4M3FN.ir_type
        f32 = T.f32
        i64 = T.i64
        vec4_f32 = T.vec(4, f32)
        vec16_x = T.vec(16, x_elem)
        vec2_i64 = T.vec(2, i64)

        def ptr_buffer_resource(ptr, num_records_bytes):
            addr = fx.ptrtoint(ptr)
            addr_i64 = arith.index_cast(T.i64, addr)
            return _bo_create_buffer_resource_from_addr(addr_i64, num_records_bytes=num_records_bytes)

        acc_init = arith.constant_vector(0.0, vec4_f32)
        c_n_total = arith.constant(experts * (2 * inter_dim), index=True)
        layout_b = make_preshuffle_b_layout(c_n=c_n_total, c_k=k_in // b_byte_div, kpack_bytes=kpack_bytes)
        sorted_m = size_expert_ids_in * arith.constant(sort_block_m, index=True)
        layout_scale = make_preshuffle_scale_layout(c_k=arith.constant(model_dim, index=True))
        shape_lds = fx.make_shape(tile_m, lds_stride)
        stride_lds = fx.make_stride(lds_stride, 1)
        layout_lds = fx.make_layout(shape_lds, stride_lds)
        tx = gpu.thread_id("x")
        by = gpu.block_id("x")
        bx_persist = gpu.block_id("y")
        by_n = by * arith.constant(tile_n, index=True)
        k_base_idx = arith.index(0)
        k_blocks16 = arith.constant(tile_k // 16, index=True)
        layout_tx_wave_lane = fx.make_layout((num_waves, 64), stride=(64, 1))
        layout_lane16 = fx.make_layout((4, 16), stride=(16, 1))
        base_ptr_pong = allocator_pong.get_base()
        base_ptr_ping = allocator_ping.get_base()
        lds_x_pong = SmemPtr(
            base_ptr_pong, lds_pong_offset, fx.Float8E4M3FN.ir_type, shape=(single_x_bytes,)
        ).get()
        lds_x_ping = SmemPtr(
            base_ptr_ping, lds_ping_offset, fx.Float8E4M3FN.ir_type, shape=(single_x_bytes,)
        ).get()
        lds_out = SmemPtr(base_ptr_pong, lds_pong_offset, T.f32, shape=(tile_m * tile_n,)).get()
        lds_tid = SmemPtr(base_ptr_pong, lds_tid_offset_pong, T.i32, shape=(tile_m,)).get()
        x_nbytes_idx = tokens_in * k_in
        x_nbytes_i32 = arith.index_cast(T.i32, x_nbytes_idx)
        x_rsrc = ptr_buffer_resource(arg_x, x_nbytes_i32)
        numids_rsrc = ptr_buffer_resource(arg_num_valid_ids, arith.constant(4, type=T.i32))
        num_valid_i32 = _bo_buffer_load(numids_rsrc, arith.constant(0, index=True), vec_width=1, dtype=T.i32)
        c32 = arith.constant(32, index=True)
        kblk = k_in // c32
        scale_rows = (
            (sorted_m + arith.constant(31, index=True))
            // arith.constant(32, index=True)
            * arith.constant(32, index=True)
        )
        sx_nbytes_idx = scale_rows * kblk
        sx_nbytes_i32 = arith.index_cast(T.i32, sx_nbytes_idx)
        sx_rsrc = ptr_buffer_resource(arg_scale_x, sx_nbytes_i32)
        c32 = arith.constant(32, index=True)
        kblk_w = k_in // c32
        mn_w = arith.constant(experts * (2 * inter_dim), index=True)
        sw_nbytes_idx = mn_w * kblk_w
        sw_nbytes_i32 = arith.index_cast(T.i32, sw_nbytes_idx)
        sw_rsrc = ptr_buffer_resource(arg_scale_w, sw_nbytes_i32)
        sorted_nbytes_idx = size_expert_ids_in * arith.constant(sort_block_m * 4, index=True)
        sorted_nbytes_i32 = arith.index_cast(T.i32, sorted_nbytes_idx)
        sorted_rsrc = ptr_buffer_resource(arg_sorted_token_ids, sorted_nbytes_i32)
        eid_nbytes_idx = size_expert_ids_in * arith.constant(4, index=True)
        eid_nbytes_i32 = arith.index_cast(T.i32, eid_nbytes_idx)
        expert_rsrc = ptr_buffer_resource(arg_expert_ids, eid_nbytes_i32)
        sorted_scale_cols = (inter_dim // 32 + 7) // 8 * 8
        sorted_scale_cols_i32 = arith.constant(sorted_scale_cols, type=T.i32)
        sort_rows_idx = size_expert_ids_in * arith.constant(sort_block_m, index=True)
        sort_padded_rows = (
            (sort_rows_idx + arith.constant(255, index=True))
            // arith.constant(256, index=True)
            * arith.constant(256, index=True)
        )
        sort_padded_cols = arith.constant((sorted_scale_cols + 7) // 8 * 8, index=True)
        sort_scale_nbytes = arith.index_cast(T.i32, sort_padded_rows * sort_padded_cols)
        sorted_scale_rsrc = ptr_buffer_resource(arg_out_scale_sorted, sort_scale_nbytes)
        bx = bx_persist
        bx_m = bx * arith.constant(sort_block_m, index=True)
        bx_m_i32 = arith.index_cast(T.i32, bx_m)

        blk_valid = arith.cmpi(CmpIPredicate.ult, bx_m_i32, num_valid_i32)
        expert_i32 = _bo_buffer_load(expert_rsrc, bx, vec_width=1, dtype=T.i32)
        pre_rows = []
        pre_layout = fx.make_layout((tile_m, tile_k_dwords), stride=(tile_k_dwords, 1))
        pre_base = tx * arith.constant(4, index=True)
        for i in range_constexpr(num_x_loads):
            row_local_pre, _ = tile_chunk_coord_i32(
                tx_i32_base=pre_base,
                i=i,
                total_threads=total_threads,
                layout_tile_div4=pre_layout,
                chunk_i32=4,
            )
            pre_rows.append(_bo_buffer_load(sorted_rsrc, bx_m + row_local_pre, vec_width=1, dtype=T.i32))
        pre_tid = _bo_buffer_load(sorted_rsrc, bx_m + tx, vec_width=1, dtype=T.i32)
        rocdl.sched_barrier(0)
        expert_i32 = rocdl.ReadfirstlaneOp(T.i32, expert_i32).res
        expert_idx = arith.index_cast(ir.IndexType.get(), expert_i32)
        exp_valid = arith.cmpi(CmpIPredicate.ult, expert_i32, arith.constant(experts, type=T.i32))

        def moe_gemm1_body():
            body_k_base_idx = k_base_idx
            body_vmcnt_before_barrier = tile_m // 32 + tile_n // 32
            expert_off_idx = expert_idx * arith.constant(2 * inter_dim, index=True)

            def mixed_b_mfma(a128, b128, acc, opsel_a, a_scale_val, opsel_b, b_scale_val):
                return rocdl.mfma_scale_f32_16x16x128_f8f6f4(
                    vec4_f32, [a128, b128, acc, cbsz, blgp, opsel_a, a_scale_val, opsel_b, b_scale_val]
                )

            per_expert_w_bytes = w_nbytes // experts
            w_addr_i64 = arith.index_cast(T.i64, fx.ptrtoint(arg_w))
            expert_byte_off = arith.index_cast(
                T.i64, expert_idx * arith.constant(per_expert_w_bytes, index=True)
            )
            w_rsrc_e = _bo_create_buffer_resource_from_addr(
                arith.addi(w_addr_i64, expert_byte_off), num_records_bytes=per_expert_w_bytes
            )
            chunk_i32 = 4
            c_k_div4 = k_in // arith.index(4)
            layout_x_tile_div4 = fx.make_layout((tile_m, tile_k_dwords), stride=(tile_k_dwords, 1))
            c_chunk_i32 = arith.constant(chunk_i32, index=True)
            tx_i32_base = tx * c_chunk_i32
            topk_i32 = arith.constant(topk)
            mask24 = arith.constant(16777215)
            tokens_i32 = arith.index_cast(T.i32, tokens_in)

            def x_tile_chunk_coord_i32(i: int):
                return tile_chunk_coord_i32(
                    tx_i32_base=tx_i32_base,
                    i=i,
                    total_threads=total_threads,
                    layout_tile_div4=layout_x_tile_div4,
                    chunk_i32=chunk_i32,
                )

            x_row_base_div4 = []
            x_col_local_i32 = []
            x_row_local = []
            for i in range_constexpr(num_x_loads):
                row_local, col_local_i32 = x_tile_chunk_coord_i32(i)
                x_row_local.append(row_local)
                x_col_local_i32.append(col_local_i32)
                fused_i = pre_rows[i]
                t_i32 = arith.andi(fused_i, mask24)
                s_i32 = arith.shrui(fused_i, arith.constant(24))
                t_valid = arith.cmpi(CmpIPredicate.ult, t_i32, tokens_i32)
                s_valid = arith.cmpi(CmpIPredicate.ult, s_i32, topk_i32)
                ts_valid = arith.andi(t_valid, s_valid)
                t_safe = arith.select(ts_valid, t_i32, arith.constant(0))
                t_idx = arith.index_cast(ir.IndexType.get(), t_safe)
                x_row_base_div4.append(t_idx * c_k_div4)
            coord_wl = idx2crd(fx.Int32(tx), layout_tx_wave_lane)
            wave_id = get(coord_wl, 0)
            lane_id = get(coord_wl, 1)
            coord_l16 = idx2crd(fx.Int32(lane_id), layout_lane16)
            lane_div_16 = get(coord_l16, 0)
            lane_mod_16 = get(coord_l16, 1)
            row_a_lds = lane_mod_16
            col_offset_base = lane_div_16 * arith.constant(16, index=True)
            num_acc_n = n_per_wave // 16
            c_n_per_wave = arith.constant(n_per_wave, index=True)
            wave_n_id = wave_id % arith.constant(num_waves, index=True)
            n_tile_base = wave_n_id * c_n_per_wave
            gate_n_intra_list = []
            gate_n_blk_list = []
            col_g_list = []
            c_n0_static = experts * (2 * inter_dim) // 16
            layout_n_blk_intra = fx.make_layout((c_n0_static, 16), stride=(16, 1))
            for i in range_constexpr(num_acc_n):
                offset = i * 16
                c_offset = arith.constant(offset, index=True)
                global_n = by_n + n_tile_base + c_offset + lane_mod_16
                gate_row_w = global_n
                gate_coord = idx2crd(fx.Int32(gate_row_w), layout_n_blk_intra)
                gate_n_blk_list.append(get(gate_coord, 0))
                gate_n_intra_list.append(get(gate_coord, 1))
            gui_num_acc_n_out = num_acc_n // pack_N
            for gui_i in range_constexpr(gui_num_acc_n_out):
                gui_offset = gui_i * 16
                gui_c_offset = arith.constant(gui_offset, index=True)
                gui_col_g = (by_n + n_tile_base) // arith.constant(2, index=True) + gui_c_offset + lane_mod_16
                col_g_list.append(gui_col_g)
            m_repeat = tile_m // 16
            k_unroll = tile_k // 128
            k_unroll_packed = k_unroll // pack_K
            m_repeat_packed = m_repeat // pack_M
            num_acc_n_packed = num_acc_n // pack_N

            def load_b_packs_k64(base_k, ku: int, n_blk, n_intra):
                coord_pack = (
                    n_blk,
                    base_k // arith.constant(64, index=True) + arith.constant(ku, index=True),
                    lane_div_16,
                    n_intra,
                    arith.constant(0, index=True),
                )
                idx_pack = crd2idx(coord_pack, layout_b)
                b16 = _buffer_load_vec(
                    w_rsrc_e,
                    idx_pack,
                    elem_type=T.i8,
                    vec_elems=kpack_bytes,
                    offset_in_bytes=True,
                    cache_modifier=b_nt,
                )
                b_i64x2 = _vec_bitcast(vec2_i64, b16)
                return (_vec_extract(b_i64x2, 0), _vec_extract(b_i64x2, 1))

            def load_b_tile(base_k):
                gate_b_tile = []
                for ku in range_constexpr(k_unroll):
                    g_packs0, g_packs1 = ([], [])
                    for ni in range_constexpr(num_acc_n):
                        gb = load_b_packs_k64(base_k, ku, gate_n_blk_list[ni], gate_n_intra_list[ni])
                        g_packs0.append(gb[0])
                        g_packs1.append(gb[1])
                    gate_b_tile.append((g_packs0, g_packs1))
                return gate_b_tile

            scale_lane_elem = lane_div_16 * layout_scale.stride_klane + lane_mod_16
            gate_scale_bases = []
            for ni in range_constexpr(num_acc_n_packed):
                col_base = by_n + n_tile_base + arith.constant(ni * 16 * pack_N, index=True)
                gate_mni = (expert_off_idx + col_base) // arith.constant(32, index=True)
                gate_scale_bases.append(gate_mni * layout_scale.stride_n0 + scale_lane_elem)
            a_scale_bases = []
            for mi in range_constexpr(m_repeat_packed):
                a_mni = mi + bx_m // scale_mn_pack // 16
                a_scale_bases.append(a_mni * layout_scale.stride_n0 + scale_lane_elem)
            c16_idx = arith.constant(16, index=True)
            c2_idx = arith.constant(2, index=True)
            scale_mask_lo = arith.constant(255, type=T.i32)
            if const_expr(pack_M < scale_mn_pack):
                m_half_idx = bx_m // c16_idx % c2_idx
                m_half_i32 = arith.index_cast(T.i32, m_half_idx)
                scale_shift = m_half_i32 * arith.constant(8, type=T.i32)
                scale_shift_hi = scale_shift + arith.constant(16, type=T.i32)

            def rearrange_a_scale(raw_i32):
                if const_expr(pack_M >= scale_mn_pack):
                    return raw_i32
                b_k0 = arith.andi(arith.shrui(raw_i32, scale_shift), scale_mask_lo)
                b_k1 = arith.andi(arith.shrui(raw_i32, scale_shift_hi), scale_mask_lo)
                return arith.ori(b_k0, arith.shli(b_k1, arith.constant(8, type=T.i32)))

            def prefetch_ab_scale_tile(base_k):
                a_scale_tile = []
                gate_b_scale = []
                for ku in range_constexpr(k_unroll_packed):
                    k_off = (ku + base_k) * layout_scale.stride_k0
                    for mi in range_constexpr(m_repeat_packed):
                        s = _bo_buffer_load(
                            sx_rsrc, a_scale_bases[mi] + k_off, vec_width=1, dtype=T.i32, cache_modifier=0
                        )
                        s = rearrange_a_scale(s)
                        a_scale_tile.append(_vec_from_elements(T.vec(1, T.i32), [s]))
                    for ni in range_constexpr(num_acc_n_packed):
                        gs = _bo_buffer_load(
                            sw_rsrc, gate_scale_bases[ni] + k_off, vec_width=1, dtype=T.i32, cache_modifier=0
                        )
                        gate_b_scale.append(_vec_from_elements(T.vec(1, T.i32), [gs]))
                return [a_scale_tile, gate_b_scale]

            dma_bytes = 16
            wave_size = 64
            num_dma_loads = max(1, single_x_bytes // (total_threads * dma_bytes))

            def prefetch_x_to_lds(base_k, lds_buffer):
                c4_idx = arith.index(4)
                base_k_div4 = base_k // arith.index(4)
                lds_ptr_i64 = None
                for i in range_constexpr(num_dma_loads):
                    row_local_i = x_row_local[i]
                    col_local_i32_i = x_col_local_i32[i]
                    col_local_sw = swizzle_xor16(row_local_i, col_local_i32_i * c4_idx, k_blocks16)
                    row_k_dw = x_row_base_div4[i] + base_k_div4
                    global_byte_idx = row_k_dw * c4_idx + col_local_sw
                    global_offset = arith.index_cast(T.i32, global_byte_idx)
                    if const_expr(i == 0):
                        lds_addr = memref.extract_aligned_pointer_as_index(
                            lds_buffer
                        ) + wave_n_id * arith.constant(wave_size * dma_bytes, index=True)
                        lds_ptr_i64 = rocdl.readfirstlane(T.i64, arith.index_cast(T.i64, lds_addr))
                    else:
                        lds_ptr_i64 = lds_ptr_i64 + arith.constant(total_threads * dma_bytes, type=T.i64)
                    lds_ptr_type = ir.Type.parse("!llvm.ptr<3>")
                    lds_ptr = llvm.inttoptr(lds_ptr_type, lds_ptr_i64)
                    rocdl.raw_ptr_buffer_load_lds(
                        x_rsrc,
                        lds_ptr,
                        arith.constant(dma_bytes, type=T.i32),
                        global_offset,
                        arith.constant(0, type=T.i32),
                        arith.constant(0, type=T.i32),
                        arith.constant(0, type=T.i32),
                    )

            def lds_load_packs_k64(curr_row_a_lds, col_base, lds_buffer):
                col_base_swz_bytes = swizzle_xor16(curr_row_a_lds, col_base, k_blocks16)
                col_base_swz = col_base_swz_bytes
                idx_a16 = crd2idx([fx.Int32(curr_row_a_lds), fx.Int32(col_base_swz)], layout_lds)
                loaded_a16 = _vec_load_op(vec16_x, lds_buffer, [idx_a16])
                a_i64x2 = _vec_bitcast(vec2_i64, loaded_a16)
                a0 = _vec_extract(a_i64x2, 0)
                a1 = _vec_extract(a_i64x2, 1)
                return (a0, a1)

            def prefetch_full_a_from_lds(lds_buffer):
                a_regs = []
                for k_idx in range_constexpr(k_unroll):
                    col_base = col_offset_base + k_idx * 128
                    for mi_idx in range_constexpr(m_repeat):
                        mi_val = arith.constant(mi_idx * 16, index=True)
                        curr_row = row_a_lds + mi_val
                        a0, a1 = lds_load_packs_k64(curr_row, col_base, lds_buffer)
                        a2, a3 = lds_load_packs_k64(curr_row, col_base + 64, lds_buffer)
                        a_regs.append((a0, a1, a2, a3))
                return a_regs

            def compute_tile(acc_gate_in, gate_b_tile_in, a_tile_regs, a_scale, gate_b_scale):
                gate_list = list(acc_gate_in)
                c0_i64 = arith.constant(0, type=T.i64)
                vec4_i64 = T.vec(4, T.i64)
                vec8_i32 = T.vec(8, T.i32)

                def pack_i64x4_to_i32x8(x0, x1, x2, x3):
                    v4 = _vec_from_elements(vec4_i64, [x0, x1, x2, x3])
                    return _vec_bitcast(vec8_i32, v4)

                for ku128 in range_constexpr(k_unroll_packed):
                    for ni in range_constexpr(num_acc_n_packed):
                        gate_bs_i32 = gate_b_scale[ku128 * num_acc_n_packed + ni]
                        gate_bs_val = _vec_extract(gate_bs_i32, 0)
                        for ikxdl in range_constexpr(pack_K):
                            k_idx = ku128 * pack_K + ikxdl
                            gate_bp = gate_b_tile_in[k_idx]
                            for inxdl in range_constexpr(pack_N):
                                ni_idx = ni * pack_N + inxdl
                                gb128 = pack_i64x4_to_i32x8(
                                    gate_bp[0][ni_idx], gate_bp[1][ni_idx], c0_i64, c0_i64
                                )
                                for mi in range_constexpr(m_repeat_packed):
                                    a_scale_i32 = a_scale[ku128 * m_repeat_packed + mi]
                                    a_scale_val = _vec_extract(a_scale_i32, 0)
                                    for imxdl in range_constexpr(pack_M):
                                        mi_idx = mi * pack_M + imxdl
                                        a_reg_idx = k_idx * m_repeat + mi_idx
                                        a0, a1, a2, a3 = a_tile_regs[a_reg_idx]
                                        a128 = pack_i64x4_to_i32x8(a0, a1, a2, a3)
                                        acc_idx = mi_idx * num_acc_n + ni_idx
                                        gate_list[acc_idx] = mixed_b_mfma(
                                            a128,
                                            gb128,
                                            gate_list[acc_idx],
                                            ikxdl * pack_M + imxdl,
                                            a_scale_val,
                                            ikxdl * pack_N + inxdl,
                                            gate_bs_val,
                                        )
                return gate_list

            def load_a_subtile(k_idx, mi_idx, lds_buffer):
                col_base = col_offset_base + k_idx * 128
                mi_val = arith.constant(mi_idx * 16, index=True)
                curr_row = row_a_lds + mi_val
                a0, a1 = lds_load_packs_k64(curr_row, col_base, lds_buffer)
                a2, a3 = lds_load_packs_k64(curr_row, col_base + 64, lds_buffer)
                return (a0, a1, a2, a3)

            def compute_bmajor_mfma_phase(
                all_a_tiles, gate_b_single, a_scale_vals, gate_bs_val, gate_list, k_idx, ni_idx, ikxdl, inxdl
            ):
                """B-major MFMA: pack one B (ni) once and run it against every A tile (mi), already in
                registers. ``all_a_tiles`` is indexed by k * m_repeat + mi, ``a_scale_vals`` by packed mi."""
                c0_i64 = arith.constant(0, type=T.i64)
                vec4_i64 = T.vec(4, T.i64)
                vec8_i32 = T.vec(8, T.i32)

                def pack(x0, x1, x2, x3):
                    v4 = _vec_from_elements(vec4_i64, [x0, x1, x2, x3])
                    return _vec_bitcast(vec8_i32, v4)

                gb128 = pack(gate_b_single[0], gate_b_single[1], c0_i64, c0_i64)
                for mi_p in range_constexpr(m_repeat_packed):
                    a_scale_val = a_scale_vals[mi_p]
                    for imxdl in range_constexpr(pack_M):
                        mi_idx = mi_p * pack_M + imxdl
                        a_reg = all_a_tiles[k_idx * m_repeat + mi_idx]
                        a128 = pack(a_reg[0], a_reg[1], a_reg[2], a_reg[3])
                        acc_idx = mi_idx * num_acc_n + ni_idx
                        gate_list[acc_idx] = mixed_b_mfma(
                            a128,
                            gb128,
                            gate_list[acc_idx],
                            ikxdl * pack_M + imxdl,
                            a_scale_val,
                            ikxdl * pack_N + inxdl,
                            gate_bs_val,
                        )

            def interleaved_half(
                lds_read,
                lds_write,
                next_k_dma_py,
                next_k_load,
                prev_a_tile,
                prev_gate_w,
                prev_a_scale,
                prev_gate_bs,
                acc_gate,
            ):
                """One half-iteration: the previous tile's MFMAs, split in phases, with the next tile's A DMA,
                scale and B loads and the A sub-tile LDS reads interleaved between them."""
                abs_k = body_k_base_idx + arith.constant(next_k_load, index=True)
                bk = abs_k // arith.constant(b_byte_div, index=True)
                sk = abs_k // arith.constant(pack_K * 128, index=True)
                k_off = sk * layout_scale.stride_k0
                rocdl.sched_barrier(0)
                rocdl.s_waitcnt(body_vmcnt_before_barrier)
                barrier()
                rocdl.sched_barrier(0)
                abs_k_dma = body_k_base_idx + arith.constant(next_k_dma_py, index=True)
                if const_expr(next_k_dma_py < int(model_dim)):
                    prefetch_x_to_lds(abs_k_dma, lds_write)
                prev_asvs = []
                for i_as in range_constexpr(len(prev_a_scale)):
                    prev_asvs.append(_vec_extract(prev_a_scale[i_as], 0))
                prev_gsv_list = []
                for i_gs in range_constexpr(len(prev_gate_bs)):
                    prev_gsv_list.append(_vec_extract(prev_gate_bs[i_gs], 0))
                a_all = {}
                b_gate_all = {}
                for _p in range_constexpr(pipe_n_phases):
                    if const_expr(pp_has_scale[_p]):
                        new_as_list = []
                        new_gs_list = []
                        for ku_s in range_constexpr(k_unroll_packed):
                            ku_off = k_off + arith.constant(ku_s, index=True) * layout_scale.stride_k0
                            for mi_p in range_constexpr(m_repeat_packed):
                                raw_as = _bo_buffer_load(
                                    sx_rsrc,
                                    a_scale_bases[mi_p] + ku_off,
                                    vec_width=1,
                                    dtype=T.i32,
                                    cache_modifier=0,
                                )
                                new_as_list.append(rearrange_a_scale(raw_as))
                            for gs_ni in range_constexpr(num_acc_n_packed):
                                gs_raw = _bo_buffer_load(
                                    sw_rsrc,
                                    gate_scale_bases[gs_ni] + ku_off,
                                    vec_width=1,
                                    dtype=T.i32,
                                    cache_modifier=0,
                                )
                                new_gs_list.append(gs_raw)
                    for b_j in range_constexpr(len(pp_b_loads[_p])):
                        b_ku, b_ni = pp_b_loads[_p][b_j]
                        b_gate_all[b_ku, b_ni] = load_b_packs_k64(
                            bk, b_ku, gate_n_blk_list[b_ni], gate_n_intra_list[b_ni]
                        )
                    rocdl.sched_barrier(0)
                    for a_j in range_constexpr(len(pp_a_reads[_p])):
                        ak, ami = pp_a_reads[_p][a_j]
                        a_all[ak, ami] = load_a_subtile(ak, ami, lds_read)
                    rocdl.sched_barrier(0)
                    rocdl.s_setprio(1)
                    for m_j in range_constexpr(len(pp_mfma[_p])):
                        k_idx, ni_idx, ikxdl, inxdl, ku128 = pp_mfma[_p][m_j]
                        ni_packed_idx = ni_idx // pack_N
                        as_off = ku128 * m_repeat_packed
                        bs_idx = ku128 * num_acc_n_packed + ni_packed_idx
                        gate_w = prev_gate_w[k_idx]
                        compute_bmajor_mfma_phase(
                            prev_a_tile,
                            (gate_w[0][ni_idx], gate_w[1][ni_idx]),
                            prev_asvs[as_off : as_off + m_repeat_packed],
                            prev_gsv_list[bs_idx],
                            acc_gate,
                            k_idx,
                            ni_idx,
                            ikxdl,
                            inxdl,
                        )
                    rocdl.s_setprio(0)
                    rocdl.sched_barrier(0)
                cur_a_tile = []
                for k in range_constexpr(k_unroll):
                    for mi in range_constexpr(m_repeat):
                        cur_a_tile.append(a_all[k, mi])
                cur_gate_w = []
                for ku in range_constexpr(k_unroll):
                    g_packs0, g_packs1 = ([], [])
                    for ni in range_constexpr(num_acc_n):
                        g = b_gate_all[ku, ni]
                        g_packs0.append(g[0])
                        g_packs1.append(g[1])
                    cur_gate_w.append((g_packs0, g_packs1))
                cur_a_scale = []
                for i_as in range_constexpr(len(new_as_list)):
                    cur_a_scale.append(_vec_from_elements(T.vec(1, T.i32), [new_as_list[i_as]]))
                cur_gate_bs = []
                for i_gs in range_constexpr(len(new_gs_list)):
                    cur_gate_bs.append(_vec_from_elements(T.vec(1, T.i32), [new_gs_list[i_gs]]))
                return (cur_a_tile, cur_gate_w, cur_a_scale, cur_gate_bs, acc_gate)

            rocdl.sched_barrier(0)
            k0 = body_k_base_idx
            k0_b = body_k_base_idx // arith.constant(b_byte_div, index=True)
            gate_w0 = load_b_tile(k0_b)
            k0_scale = body_k_base_idx // arith.constant(pack_K * 128, index=True)
            a_scale_pong, gate_bs_pong = prefetch_ab_scale_tile(k0_scale)
            rocdl.sched_barrier(0)
            prefetch_x_to_lds(k0, lds_x_pong)
            k1 = body_k_base_idx + arith.constant(tile_k, index=True)
            prefetch_x_to_lds(k1, lds_x_ping)
            rocdl.sched_barrier(0)
            c_tile_m_idx = arith.constant(tile_m, index=True)
            if_tid = scf.IfOp(arith.cmpi(CmpIPredicate.ult, tx, c_tile_m_idx))
            with ir.InsertionPoint(if_tid.then_block):
                tid_vec1 = _vec_from_elements(T.vec(1, T.i32), [pre_tid])
                _vec_store(tid_vec1, lds_tid, [tx])
                scf.YieldOp([])
            acc_gate = [acc_init] * num_acc_n * m_repeat
            rocdl.s_waitcnt(0)
            gpu.barrier()
            rocdl.sched_barrier(0)
            a_tile_pong = prefetch_full_a_from_lds(lds_x_pong)
            rocdl.sched_barrier(0)
            rocdl.s_waitcnt(6)
            num_k_tiles_py = int(model_dim) // int(tile_k)
            assert num_k_tiles_py % 2 == 0 and num_k_tiles_py >= 4
            k_main2_py = (num_k_tiles_py - 2) * int(tile_k)
            gate_w_pong = gate_w0
            rocdl.sched_barrier(0)
            for k_iv_py in range_constexpr(0, k_main2_py, tile_k * 2):
                next_k_load_1 = k_iv_py + tile_k
                next_k_load_2 = k_iv_py + tile_k * 2
                next_k_dma_1 = k_iv_py + tile_k * 2
                next_k_dma_2 = k_iv_py + tile_k * 3
                a_tile_ping, gate_w_ping, a_scale_ping, gate_bs_ping, acc_gate = interleaved_half(
                    lds_x_ping,
                    lds_x_pong,
                    next_k_dma_1,
                    next_k_load_1,
                    a_tile_pong,
                    gate_w_pong,
                    a_scale_pong,
                    gate_bs_pong,
                    acc_gate,
                )
                a_tile_pong, gate_w_pong, a_scale_pong, gate_bs_pong, acc_gate = interleaved_half(
                    lds_x_pong,
                    lds_x_ping,
                    next_k_dma_2,
                    next_k_load_2,
                    a_tile_ping,
                    gate_w_ping,
                    a_scale_ping,
                    gate_bs_ping,
                    acc_gate,
                )
            k_tail_rel = arith.constant(model_dim - tile_k, index=True)
            k_tail1 = body_k_base_idx + k_tail_rel
            prefetch_x_to_lds(k_tail1, lds_x_ping)
            gate_w_ping = load_b_tile(k_tail1 // arith.constant(b_byte_div, index=True))
            a_scale_ping, gate_bs_ping = prefetch_ab_scale_tile(
                k_tail1 // arith.constant(pack_K * 128, index=True)
            )
            acc_gate = compute_tile(acc_gate, gate_w_pong, a_tile_pong, a_scale_pong, gate_bs_pong)
            rocdl.s_waitcnt(0)
            barrier()
            a_tile_ping = prefetch_full_a_from_lds(lds_x_ping)
            acc_gate = compute_tile(acc_gate, gate_w_ping, a_tile_ping, a_scale_ping, gate_bs_ping)

            def sigmoid_elem(g):
                neg_log2e = arith.constant(-1.4426950408889634, type=f32)
                t = g * neg_log2e
                emu = llvm.call_intrinsic(f32, "llvm.amdgcn.exp2.f32", [t], [], [])
                one = arith.constant(1.0, type=f32)
                den = one + emu
                return llvm.call_intrinsic(f32, "llvm.amdgcn.rcp.f32", [den], [], [])

            def silu_elem(g):
                return g * sigmoid_elem(g)

            def _clamp_gate(x):
                return -(-x).maximumf(swiglu_neg_limit)

            def _clamp_lin(x):
                return (-(-x).maximumf(swiglu_neg_limit)).maximumf(swiglu_neg_limit)

            def silu_mul_vec4(gate_v4, up_v4):
                result_elems = []
                for ei in range_constexpr(4):
                    g = _vec_extract(gate_v4, ei)
                    u = _vec_extract(up_v4, ei)
                    g = _clamp_gate(g)
                    u = _clamp_lin(u)
                    result_elems.append(silu_elem(g) * u)
                return _vec_from_elements(vec4_f32, result_elems)

            gui_out_n = num_acc_n // pack_N
            acc = [None] * (gui_out_n * m_repeat)
            for mi in range_constexpr(m_repeat):
                for ni in range_constexpr(gui_out_n):
                    g_idx = mi * num_acc_n + ni * pack_N
                    u_idx = g_idx + 1
                    out_idx = mi * gui_out_n + ni
                    acc[out_idx] = silu_mul_vec4(acc_gate[g_idx], acc_gate[u_idx])
            mask24_i32 = arith.constant(16777215)
            topk_i32_v = topk_i32
            tokens_i32_v = tokens_i32
            out_base_i64 = arith.index_cast(T.i64, fx.ptrtoint(arg_out))
            out_base_idx = arith.index_cast(ir.IndexType.get(), out_base_i64)

            def write_row_to_lds(*, mi: int, ii: int, row_base_lds, col_base_local, num_acc_n: int, lds_out):
                for ni in range_constexpr(num_acc_n):
                    col_local = col_base_local + ni * 16
                    acc_idx = mi * num_acc_n + ni
                    v = _vec_extract(acc[acc_idx], ii)
                    lds_idx = row_base_lds + col_local
                    vec1_f32 = T.vec(1, f32)
                    v1 = _vec_from_elements(vec1_f32, [v])
                    _vec_store(v1, lds_out, [lds_idx], alignment=4)

            out_row_stride = inter_dim

            def precompute_row(*, row_local, row):
                fused2 = memref.load(lds_tid, [row_local])
                row_i32 = arith.index_cast(T.i32, row)
                row_valid0 = arith.cmpi(CmpIPredicate.ult, row_i32, num_valid_i32)
                t = fused2 & mask24_i32
                s = fused2 >> 24
                t_ok = arith.cmpi(CmpIPredicate.ult, t, tokens_i32_v)
                s_ok = arith.cmpi(CmpIPredicate.ult, s, topk_i32_v)
                row_valid = arith.andi(row_valid0, arith.andi(t_ok, s_ok))
                t_idx = arith.index_cast(ir.IndexType.get(), t)
                s_idx = arith.index_cast(ir.IndexType.get(), s)
                ts_idx = t_idx * arith.constant(topk, index=True) + s_idx
                payload_row_idx = ts_idx
                row_byte_base = out_base_idx + payload_row_idx * arith.constant(out_row_stride, index=True)
                return (row_byte_base, row_valid)

            def idx_to_llvm_ptr(idx_val, addr_space=1):
                idx_v = idx_val._value if hasattr(idx_val, "_value") else idx_val
                i64_v = arith.index_cast(T.i64, idx_v)
                i64_raw = i64_v._value if hasattr(i64_v, "_value") else i64_v
                ptr_ty = ir.Type.parse(f"!llvm.ptr<{addr_space}>")
                return llvm.inttoptr(ptr_ty, i64_raw)

            e_vec = e_vec_s1
            c0_i32 = arith.constant(0, type=T.i32)
            c1_i32 = arith.constant(1, type=T.i32)
            c2_i32 = arith.constant(2, type=T.i32)
            c3_i32 = arith.constant(3, type=T.i32)
            c4_i32 = arith.constant(4, type=T.i32)
            c5_i32 = arith.constant(5, type=T.i32)
            c15_i32 = arith.constant(15, type=T.i32)
            c23_i32 = arith.constant(23, type=T.i32)
            c31_i32 = arith.constant(31, type=T.i32)
            c32_i32 = arith.constant(32, type=T.i32)
            c64_i32 = arith.constant(64, type=T.i32)
            c254_i32 = arith.constant(254, type=T.i32)
            c256_i32 = arith.constant(256, type=T.i32)
            c0xFF800000_i32 = arith.constant(4286578688, type=T.i32)
            c0x400000_i32 = arith.constant(4194304, type=T.i32)
            c0_f32 = arith.constant(0.0, type=T.f32)
            c_headroom_i32 = arith.constant(8, type=T.i32)
            n32_sort = sorted_scale_cols_i32 * c32_i32

            def store_pair(*, row, row_ctx, col_g0, frag):
                row_byte_base = row_ctx
                frag_vals = []
                for i in range_constexpr(e_vec):
                    frag_vals.append(_vec_extract(frag, i))
                local_max = c0_f32
                for i in range_constexpr(e_vec):
                    abs_v = llvm.call_intrinsic(f32, "llvm.fabs.f32", [frag_vals[i]], [], [])
                    local_max = arith.maximumf(local_max, abs_v)
                _dpp_ctl = {1: 177, 2: 78, 4: 321, 8: 296}
                assert list(shuffle_dists_s1) == [1, 2, 4, 8][:num_shuffle_steps_s1]
                for si in range_constexpr(num_shuffle_steps_s1):
                    peer_i = rocdl.update_dpp(
                        T.i32,
                        _raw(arith.constant(0, type=T.i32)),
                        _raw(local_max.bitcast(T.i32)),
                        _dpp_ctl[shuffle_dists_s1[si]],
                        15,
                        15,
                        True,
                    )
                    peer = std_arith.bitcast(T.f32, peer_i)
                    local_max = arith.maximumf(local_max, peer)
                max_i32 = local_max.bitcast(T.i32)
                max_rounded = max_i32 + c0x400000_i32 & c0xFF800000_i32
                exp_field = max_rounded >> c23_i32
                e8m0_biased = arith.maxsi(exp_field - c_headroom_i32, c0_i32)
                quant_exp = c254_i32 - e8m0_biased
                quant_scale = (quant_exp << c23_i32).bitcast(T.f32)
                scaled_vals = []
                for i in range_constexpr(e_vec):
                    scaled_vals.append(frag_vals[i] * quant_scale)
                ptr_addr_idx = row_byte_base + col_g0
                packed_i32 = c0_i32
                for w in range_constexpr(e_vec // 2):
                    packed_i32 = rocdl.cvt_pk_fp8_f32(
                        T.i32, scaled_vals[2 * w], scaled_vals[2 * w + 1], packed_i32, w
                    )
                out_ptr_v = idx_to_llvm_ptr(ptr_addr_idx)
                store_val = arith.TruncIOp(T.i16, packed_i32)
                store_raw = store_val._value if hasattr(store_val, "_value") else store_val
                llvm.StoreOp(store_raw, out_ptr_v, alignment=2, nontemporal=True)
                col_g0_i32 = arith.index_cast(T.i32, col_g0)
                is_scale_writer = arith.cmpi(CmpIPredicate.eq, col_g0_i32 & c31_i32, c0_i32)
                if_scale = scf.IfOp(is_scale_writer)
                with ir.InsertionPoint(if_scale.then_block):
                    row_i32_s = arith.index_cast(T.i32, row)
                    col_s_i32 = col_g0_i32 >> c5_i32
                    d0 = row_i32_s >> c5_i32
                    d1 = row_i32_s >> c4_i32 & c1_i32
                    d2 = row_i32_s & c15_i32
                    d3 = col_s_i32 >> c3_i32
                    d4 = col_s_i32 >> c2_i32 & c1_i32
                    d5 = col_s_i32 & c3_i32
                    byte_off = d0 * n32_sort + d3 * c256_i32 + d5 * c64_i32 + d2 * c4_i32 + d4 * c2_i32 + d1
                    e8m0_i8 = arith.TruncIOp(T.i8, e8m0_biased)
                    _bo_buffer_store_bytes(e8m0_i8, sorted_scale_rsrc, byte_off)
                    scf.YieldOp([])

            frag_elem = ir.F32Type.get()
            gui_eff_n = gui_out_n
            gui_tile_n = tile_n // 2
            gui_cshuffle_nlane = min(32, gui_tile_n // e_vec)
            gui_by_n = by_n // arith.constant(2, index=True)
            gui_n_tile_base = n_tile_base // arith.constant(2, index=True)
            c_shuffle_epilog(
                tile_m=tile_m,
                tile_n=gui_tile_n,
                e_vec=e_vec,
                cshuffle_nlane=gui_cshuffle_nlane,
                block_size=total_threads,
                m_repeat=m_repeat,
                num_acc_n=gui_eff_n,
                tx=tx,
                lane_div_16=lane_div_16,
                lane_mod_16=lane_mod_16,
                bx_m=bx_m,
                by_n=gui_by_n,
                n_tile_base=gui_n_tile_base,
                lds_out=lds_out,
                frag_elem_type=frag_elem,
                write_row_to_lds=write_row_to_lds,
                precompute_row=precompute_row,
                store_pair=store_pair,
            )

        if_blk = scf.IfOp(blk_valid)
        with ir.InsertionPoint(if_blk.then_block):
            ifexpert_of = scf.IfOp(exp_valid)
            with ir.InsertionPoint(ifexpert_of.then_block):
                moe_gemm1_body()
                scf.YieldOp([])
            scf.YieldOp([])
        gpu.barrier()

    @flyc.kernel(name=module_name, known_block_size=[total_threads, 1, 1])
    def moe_gemm1(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        arg_out_scale_sorted: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
        f32_swiglu_limit: fx.Float32,
    ):
        _emit_moe_gemm1(
            arg_out,
            arg_x,
            arg_w,
            arg_scale_x,
            arg_scale_w,
            arg_sorted_token_ids,
            arg_expert_ids,
            arg_num_valid_ids,
            arg_out_scale_sorted,
            i32_tokens_in,
            i32_k_in,
            i32_size_expert_ids_in,
            f32_swiglu_limit,
        )

    cache_tag = (module_name, waves_per_eu)

    def _launch_mixed_moe_gemm1(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        arg_out_scale_sorted: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_inter_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
        f32_swiglu_limit: fx.Float32,
        stream: fx.Stream,
    ):
        # Read so that the JIT cache key, which sees closure values, covers the configuration.
        _ = cache_tag
        allocator_pong.finalized = False
        allocator_ping.finalized = False
        ctx = CompilationContext.get_current()
        with ir.InsertionPoint(ctx.gpu_module_body):
            allocator_pong.finalize()
            allocator_ping.finalize()
        inter_in = arith.index_cast(ir.IndexType.get(), i32_inter_in.ir_value())
        tile_n_index = arith.constant(tile_n, index=True)
        gx = (inter_in + tile_n_index - 1) // tile_n_index
        gy = arith.index_cast(ir.IndexType.get(), i32_size_expert_ids_in.ir_value())
        launcher = moe_gemm1(
            arg_out,
            arg_x,
            arg_w,
            arg_scale_x,
            arg_scale_w,
            arg_sorted_token_ids,
            arg_expert_ids,
            arg_num_valid_ids,
            arg_out_scale_sorted,
            i32_tokens_in,
            i32_k_in,
            i32_size_expert_ids_in,
            f32_swiglu_limit,
        )
        launcher.launch(grid=(gx, gy, 1), block=(total_threads, 1, 1), stream=stream)

    @flyc.jit
    def launch_mixed_moe_gemm1(
        arg_out: fx.Pointer,
        arg_x: fx.Pointer,
        arg_w: fx.Pointer,
        arg_scale_x: fx.Pointer,
        arg_scale_w: fx.Pointer,
        arg_sorted_token_ids: fx.Pointer,
        arg_expert_ids: fx.Pointer,
        arg_num_valid_ids: fx.Pointer,
        arg_out_scale_sorted: fx.Pointer,
        i32_tokens_in: fx.Int32,
        i32_inter_in: fx.Int32,
        i32_k_in: fx.Int32,
        i32_size_expert_ids_in: fx.Int32,
        f32_swiglu_limit: fx.Float32,
        execute: fx.Int32,
        stream: fx.Stream,
    ):
        if execute != 0:
            _launch_mixed_moe_gemm1(
                arg_out,
                arg_x,
                arg_w,
                arg_scale_x,
                arg_scale_w,
                arg_sorted_token_ids,
                arg_expert_ids,
                arg_num_valid_ids,
                arg_out_scale_sorted,
                i32_tokens_in,
                i32_inter_in,
                i32_k_in,
                i32_size_expert_ids_in,
                f32_swiglu_limit,
                stream,
            )

    return launch_mixed_moe_gemm1


def _ptr(t):
    return flyc.from_c_void_p(fx.Uint8, t.data_ptr(), assumed_align=16)


@functools.cache
def _plan(n_tokens: int, topk: int, global_experts: int, local_experts: int, model_dim: int, inter_dim: int):
    """Static sizes for one token count (sort buffers padded as aiter's sort pads them, and the bound on the
    number of live expert blocks) and the compiled launches."""
    assert model_dim == 16 * global_experts and local_experts <= 64
    routes = n_tokens * topk
    o1, o2, bm = _CFG.get(n_tokens, ({}, {}, 32))
    max_padded = routes + global_experts * bm - topk
    max_blocks = (max_padded + bm - 1) // bm
    cap = min(max_blocks, routes, local_experts + (routes + bm - 1) // bm)

    @flyc.jit
    def prologue(
        X: fx.Pointer,
        IDS: fx.Pointer,
        RW: fx.Pointer,
        MASK: fx.Pointer,
        SID: fx.Pointer,
        SW: fx.Pointer,
        SEID: fx.Pointer,
        NV: fx.Pointer,
        A1: fx.Pointer,
        A1S: fx.Pointer,
        OUT: fx.Pointer,
        NLT: fx.Pointer,
        execute: fx.Int32,
        stream: fx.Stream,
    ):
        if execute != 0:
            _prologue(
                X,
                IDS,
                RW,
                MASK,
                SID,
                SW,
                SEID,
                NV,
                A1,
                A1S,
                OUT,
                NLT,
                n_tokens,
                topk,
                global_experts,
                local_experts,
                model_dim,
                bm,
            ).launch(grid=(n_tokens,), block=(model_dim // 16,), stream=stream)

    null = flyc.from_c_void_p(fx.Uint8, 0, assumed_align=16)
    compiled = flyc.compile(prologue, *([null] * 12), 0, fx.Stream(None))
    s1cfg = {**_S1_BASE, **o1}
    s2cfg = {**_S2_BASE, **o2}
    stage1 = _build_stage1(
        model_dim=model_dim,
        inter_dim=inter_dim,
        experts=local_experts,
        topk=topk,
        tile_m=bm,
        tile_n=s1cfg["tile_n"],
        tile_k=s1cfg["tile_k"],
        waves_per_eu=s1cfg["waves_per_eu"],
        b_nt=s1cfg["b_nt"],
    )
    stage1 = flyc.compile(
        stage1, *([null] * 9), n_tokens, 2 * inter_dim, model_dim, cap, 1.0, 0, fx.Stream(None)
    )
    s1_rows = (max(max_padded, cap * bm) + 255) // 256 * 256
    stage2 = _build_stage2(
        model_dim=model_dim,
        inter_dim=inter_dim,
        experts=local_experts,
        topk=topk,
        tile_m=bm,
        tile_n=s2cfg["tile_n"],
        tile_k=s2cfg["tile_k"],
        b_nt=s2cfg["b_nt"],
        nw=s2cfg.get("nw", 4),
        k_rot=s2cfg["k_rot"],
    )
    stage2 = flyc.compile(stage2, *([null] * 9), n_tokens, model_dim, inter_dim, cap, 0, fx.Stream(None))
    return max_padded, max_blocks, cap, compiled, stage1, s1_rows, stage2


def run(
    *,
    hidden_states,
    w1,
    w2,
    topk_weights,
    topk_ids,
    w1_scale,
    w2_scale,
    activation,
    quant_type,
    doweight_stage1,
    gate_mode,
    act_quant,
    expert_mask,
    num_local_tokens,
    beta,
    linear_beta,
    swiglu_limit,
    out_dtype,
    out,
):
    device = hidden_states.device
    n_tokens, topk = topk_ids.shape
    model_dim = hidden_states.shape[1]
    inter_dim = w1.shape[1] // 2
    max_padded, max_blocks, cap, prologue, stage1, s1_rows, stage2 = _plan(
        n_tokens, topk, expert_mask.numel(), w1.shape[0], model_dim, inter_dim
    )

    sorted_ids = torch.empty(max_padded, dtype=torch.int32, device=device)
    sorted_weights = torch.empty(max_padded, dtype=torch.float32, device=device)
    sorted_expert_ids = torch.empty(max_blocks, dtype=torch.int32, device=device)
    num_valid_ids = torch.empty(2, dtype=torch.int32, device=device)
    a1 = torch.empty((n_tokens, model_dim), dtype=torch.float8_e4m3fn, device=device)
    a1_scale = torch.empty(
        ((max_padded + 31) // 32 * 32, model_dim // 32), dtype=torch.float8_e8m0fnu, device=device
    )
    prologue(
        *(
            _ptr(x)
            for x in (
                hidden_states,
                topk_ids,
                topk_weights,
                expert_mask,
                sorted_ids,
                sorted_weights,
                sorted_expert_ids,
                num_valid_ids,
                a1,
                a1_scale,
                out,
                num_local_tokens,
            )
        ),
        1,
        fx.Stream(torch.cuda.current_stream(device)),
    )

    live_expert_ids = sorted_expert_ids[:cap]
    a2 = torch.empty((n_tokens, topk, inter_dim), dtype=torch.float8_e4m3fn, device=device)
    a2_scale = torch.empty((s1_rows, inter_dim // 32), dtype=torch.float8_e8m0fnu, device=device)
    limit = float("inf") if swiglu_limit is None else float(swiglu_limit)
    stage1(
        _ptr(a2),
        _ptr(a1),
        _ptr(w1),
        _ptr(a1_scale),
        _ptr(w1_scale),
        _ptr(sorted_ids),
        _ptr(live_expert_ids),
        _ptr(num_valid_ids),
        _ptr(a2_scale),
        n_tokens,
        2 * inter_dim,
        model_dim,
        cap,
        limit,
        1,
        fx.Stream(torch.cuda.current_stream(device)),
    )

    stage2(
        *(
            _ptr(x)
            for x in (
                out,
                a2,
                w2,
                a2_scale,
                w2_scale,
                sorted_ids,
                live_expert_ids,
                sorted_weights,
                num_valid_ids,
            )
        ),
        n_tokens,
        model_dim,
        inter_dim,
        cap,
        1,
        fx.Stream(torch.cuda.current_stream(device)),
    )
